module BurstMode #(
    parameter CFG_DATA_WIDTH = 32
) (
    input wire clk,
    input wire aresetn,
    input wire [13:0] dac_data,
    input wire [CFG_DATA_WIDTH-1:0] cfg_data,
    output wire [13:0] dac_out
);

    reg [CFG_DATA_WIDTH-1:0] r_reg, r_nxt;
    reg [13:0] dac_int;

    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            r_reg <= 0;
            dac_int <= 14'b0;
        end else begin
            r_reg <= r_nxt;
            if (cfg_data == 0) begin
                dac_int <= dac_data;
                r_reg <= 0;
            end else if (r_nxt <= cfg_data) begin
                dac_int <= dac_data;
            end else begin
                dac_int <= 14'b0;
            end
        end
    end

    always @(*) begin
        r_nxt = r_reg + 1;
    end

    assign dac_out = dac_int;

endmodule

module DFF_risingEdge (
    input D,
    input clk,
    input rst,
    output reg Q
);

always @(posedge clk or posedge rst) begin
    if (rst)
        Q <= 1'b0;
    else
        Q <= D;
end

endmodule

module ADCS7476_ctrl(
input wire clk,
input wire resetn,
output reg sclk,
output reg ss,
input wire miso,
output wire [11:0] sample_out,
output wire sample_valid
);
parameter [31:0] clk_period_ns=10;
parameter [31:0] sclk_period_ns=40;
parameter [31:0] time_between_sample_ns=20833;
parameter divider_modulo = ((sclk_period_ns / clk_period_ns) / 2) - 1;
parameter tick_between_samples = time_between_sample_ns / sclk_period_ns;
parameter [2:0]
  WAIT_SAMPLE = 0,
  ASSERT_SS = 1,
  SCLK_LOW = 2,
  SCLK_HIGH = 3,
  DEASSERT_SS = 4;
reg [2:0] cur_state; reg [2:0] next_state;
reg [15:0] bit_counter;
reg bit_counter_en; wire bit_counter_reset;
reg [15:0] clk_divider;
wire end_divider;
wire shift_in;
reg [15:0] data_reg;
wire ss_comb; reg sclk_comb; reg miso_latched;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      clk_divider <= divider_modulo;
    end else begin
      if(clk_divider == 0) begin
        clk_divider <= divider_modulo;
      end
      else begin
        clk_divider <= clk_divider - 1;
      end
    end
  end
  assign end_divider = clk_divider == 0 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      bit_counter <= {16{1'b0}};
    end else begin
      if(bit_counter_reset == 1'b1) begin
        bit_counter <= {16{1'b0}};
      end
      else if(bit_counter_en == 1'b1) begin
        bit_counter <= bit_counter + 1;
      end
    end
  end
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      cur_state <= WAIT_SAMPLE;
    end else begin
      cur_state <= next_state;
    end
  end
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      data_reg <= {16{1'b0}};
    end else begin
      if(shift_in == 1'b1) begin
        data_reg[15:1] <= data_reg[14:0];
        data_reg[0] <= miso_latched;
      end
    end
  end
  always @(cur_state, bit_counter, end_divider) begin
    next_state <= cur_state;
    case(cur_state)
    WAIT_SAMPLE : begin
      if(bit_counter == tick_between_samples && end_divider == 1'b1) begin
        next_state <= ASSERT_SS;
      end
    end
    ASSERT_SS : begin
      if(bit_counter == 1 && end_divider == 1'b1) begin
        next_state <= SCLK_LOW;
      end
    end
    SCLK_LOW : begin
      if(end_divider == 1'b1) begin
        next_state <= SCLK_HIGH;
      end
    end
    SCLK_HIGH : begin
      if(bit_counter == 15 && end_divider == 1'b1) begin
        next_state <= DEASSERT_SS;
      end
      else if(end_divider == 1'b1) begin
        next_state <= SCLK_LOW;
      end
    end
    DEASSERT_SS : begin
      if(bit_counter == 1 && end_divider == 1'b1) begin
        next_state <= WAIT_SAMPLE;
      end
    end
    default : begin
      next_state <= WAIT_SAMPLE;
    end
    endcase
  end
  always @(*) begin
    case(cur_state)
      SCLK_HIGH : bit_counter_en <= end_divider;
      SCLK_LOW : bit_counter_en <= 1'b0;
      default : bit_counter_en <= end_divider;
    endcase
  end
  assign bit_counter_reset = cur_state == ASSERT_SS && next_state == SCLK_LOW ? 1'b1 : cur_state == WAIT_SAMPLE && next_state == ASSERT_SS ? 1'b1 : cur_state == SCLK_HIGH && next_state == DEASSERT_SS ? 1'b1 : cur_state == DEASSERT_SS && next_state == WAIT_SAMPLE ? 1'b1 : 1'b0;
  assign shift_in = cur_state == SCLK_LOW && next_state == SCLK_HIGH ? 1'b1 : 1'b0;
  assign sample_valid = cur_state == SCLK_HIGH && next_state == DEASSERT_SS ? 1'b1 : 1'b0;
  assign sample_out = data_reg[12:1];
  assign ss_comb = cur_state == WAIT_SAMPLE ? 1'b1 : cur_state == DEASSERT_SS ? 1'b1 : 1'b0;
  always @(*) begin
    case(cur_state)
      SCLK_LOW : sclk_comb <= 1'b0;
      default : sclk_comb <= 1'b1;
    endcase
  end
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      ss <= 1'b1;
      sclk <= 1'b1;
      miso_latched <= 1'b0;
    end else begin
      ss <= ss_comb;
      sclk <= sclk_comb;
      miso_latched <= miso;
    end
  end
endmodule

module STD_05000_bad(
input wire i_Clock,
input wire i_Reset_n,
input wire i_D,
output wire o_Q
);
// Clock signal
// Reset signal
// D Flip-Flop input signal
// D Flip-Flop output signal
reg Q;  // D Flip-Flop output
  //CODE
  // D FlipFlop process
  always @(posedge i_Clock, posedge i_Reset_n, posedge i_D) begin
