module ssegDriver(
input wire clk,
input wire rst,
output reg [7:0] cathode_p,
output wire [7:0] anode_p,
input wire [3:0] digit1_p,
input wire [3:0] digit2_p,
input wire [3:0] digit3_p,
input wire [3:0] digit4_p,
input wire [3:0] digit5_p,
input wire [3:0] digit6_p,
input wire [3:0] digit7_p,
input wire [3:0] digit8_p
);
//----------------------------------------------
reg [31:0] digit_reg;
reg [7:0] anode_reg;
reg [3:0] digitout_reg;
reg [2:0] digit_sel;
reg [2:0] next_sel;
  //Clock and set state machine
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      digit_reg <= 32'b00000000000000000000000000000000;
      digit_sel <= 3'b000;
      next_sel <= 3'b000;
      digitout_reg <= 4'b0000;
      anode_reg <= 8'b11111111;
    end else begin
      //latch digits into register on clock edge
      digit_reg[3:0] <= digit1_p;
      digit_reg[7:4] <= digit2_p;
      digit_reg[11:8] <= digit3_p;
      digit_reg[15:12] <= digit4_p;
      digit_reg[19:16] <= digit5_p;
      digit_reg[23:20] <= digit6_p;
      digit_reg[27:24] <= digit7_p;
      digit_reg[31:28] <= digit8_p;
      digit_sel <= next_sel;
      case(digit_sel)
      3'b000 : begin
        anode_reg <= 8'b11111110;
        digitout_reg <= digit_reg[3:0];
        next_sel <= 3'b001;
      end
      3'b001 : begin
        anode_reg <= 8'b11111101;
        digitout_reg <= digit_reg[7:4];
        digit_sel <= 3'b010;
      end
      3'b010 : begin
        anode_reg <= 8'b11111011;
        digitout_reg <= digit_reg[11:8];
        next_sel <= 3'b011;
      end
      3'b011 : begin
        anode_reg <= 8'b11110111;
        digitout_reg <= digit_reg[15:12];
        next_sel <= 3'b100;
      end
      3'b100 : begin
        anode_reg <= 8'b11101111;
        digitout_reg <= digit_reg[19:16];
        next_sel <= 3'b101;
      end
      3'b101 : begin
        anode_reg <= 8'b11011111;
        digitout_reg <= digit_reg[23:20];
        next_sel <= 3'b110;
      end
      3'b110 : begin
        anode_reg <= 8'b10111111;
        digitout_reg <= digit_reg[27:24];
        next_sel <= 3'b111;
      end
      3'b111 : begin
        anode_reg <= 8'b01111111;
        digitout_reg <= digit_reg[31:28];
        next_sel <= 3'b000;
      end
      default : begin
        anode_reg <= 8'b11111111;
        digitout_reg <= 4'b0000;
        next_sel <= 3'b000;
      end
      endcase
    end
  end
  //Connect the Cathode values
  always @(*) begin
    case(digitout_reg)
      4'b0000 : cathode_p <= 8'b11000000;
  // 0 
      4'b0001 : cathode_p <= 8'b11111001;
  // 1
      4'b0010 : cathode_p <= 8'b10100100;
  // 2
      4'b0011 : cathode_p <= 8'b10110000;
  // 3
      4'b0100 : cathode_p <= 8'b10011001;
  // 4
      4'b0101 : cathode_p <= 8'b10010010;
  // 5
      4'b0110 : cathode_p <= 8'b10000010;
  // 6
      4'b0111 : cathode_p <= 8'b11111000;
  // 7
      4'b1000 : cathode_p <= 8'b10000000;
  // 8
      4'b1001 : cathode_p <= 8'b10011000;
  // 9
      4'b1010 : cathode_p <= 8'b10001000;
  // A
      4'b1011 : cathode_p <= 8'b10000011;
  // B
      4'b1100 : cathode_p <= 8'b11000110;
  // C
      4'b1101 : cathode_p <= 8'b10100001;
  // D
      4'b1110 : cathode_p <= 8'b10000110;
  // E
      4'b1111 : cathode_p <= 8'b10001110;
    endcase
  end
  // F
  //Connect the Anode values
  assign anode_p = anode_reg;
endmodule

