module h_sync #(
    parameter PULSE_LENGTH = 96,
    parameter BACK_PORCH = 48,
    parameter ACTIVE_VIDEO = 640,
    parameter FRONT_PORCH = 16
)(
    input wire clk,
    input wire rst_n,
    input wire done,
    output reg vsync_rst,
    output reg hsync,
    output reg h_de,
    output reg [9:0] pixcel_col
);

    localparam TOTAL_PIXELS = PULSE_LENGTH + BACK_PORCH + ACTIVE_VIDEO + FRONT_PORCH;

    reg [9:0] count_h;
    reg [9:0] ap_cnt;

    // State definition
    localparam IDLE = 3'd0, Sp = 3'd1, Bp = 3'd2, Ap = 3'd3, Fp = 3'd4;
    reg [2:0] state, next_state;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: next_state = done ? Sp : IDLE;
            Sp: next_state = (count_h == PULSE_LENGTH - 1) ? Bp : Sp;
            Bp: next_state = (count_h == PULSE_LENGTH + BACK_PORCH - 1) ? Ap : Bp;
            Ap: next_state = (count_h == PULSE_LENGTH + BACK_PORCH + ACTIVE_VIDEO - 1) ? Fp : Ap;
            Fp: next_state = (count_h == TOTAL_PIXELS - 1) ? Sp : Fp;
            default: next_state = IDLE;
        endcase
    end

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_h <= 10'd0;
            ap_cnt <= 10'd0;
        end else begin
            case (state)
                IDLE: begin
                    count_h <= 10'd0;
                    ap_cnt <= 10'd0;
                end
                Sp, Bp, Ap, Fp: begin
                    if (count_h == TOTAL_PIXELS - 1)
                        count_h <= 10'd0;
                    else
                        count_h <= count_h + 1'b1;

                    if (state == Ap) begin
                        if (ap_cnt == ACTIVE_VIDEO - 1)
                            ap_cnt <= 10'd0;
                        else
                            ap_cnt <= ap_cnt + 1'b1;
                    end else begin
                        ap_cnt <= 10'd0;
                    end
                end
            endcase
        end
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hsync <= 1'b1;
            h_de <= 1'b0;
            vsync_rst <= 1'b0;
            pixcel_col <= 10'd0;
        end else begin
            case (state)
                IDLE: begin
                    hsync <= 1'b1;
                    h_de <= 1'b0;
                    vsync_rst <= 1'b0;
                    pixcel_col <= 10'd0;
                end
                Sp: begin
                    hsync <= 1'b0;
                    h_de <= 1'b0;
                    vsync_rst <= (count_h == 10'd0) ? 1'b1 : 1'b0;
                    pixcel_col <= 10'd0;
                end
                Bp: begin
                    hsync <= 1'b1;
                    h_de <= 1'b0;
                    vsync_rst <= 1'b0;
                    pixcel_col <= 10'd0;
                end
                Ap: begin
                    hsync <= 1'b1;
                    h_de <= 1'b1;
                    vsync_rst <= 1'b0;
                    pixcel_col <= ap_cnt;
                end
                Fp: begin
                    hsync <= 1'b1;
                    h_de <= 1'b0;
                    vsync_rst <= 1'b0;
                    pixcel_col <= 10'd0;
                end
            endcase
        end
    end

endmodule

module mod8_adder (
