module down_counter #(
    parameter SIZE = 8
) (
    input wire clk,
    input wire en,
    input wire load_cnt,
    input wire [SIZE-1:0] d,
    output wire [SIZE-1:0] q
);

    reg [SIZE-1:0] mem;

    always @(posedge clk) begin
        if (en) begin
            if (load_cnt)
                mem <= d;
            else
                mem <= mem - 1'b1;
        end
    end

    assign q = mem;

endmodule

module register_file (
    input wire clk,
    input wire reset,
    input wire [3:0] ra1, ra2, wa3,
    input wire [31:0] wd3,
    input wire we3,
    input wire [31:0] r15,
    output wire [31:0] rd1, rd2
);

    reg [31:0] rf [14:0];
    integer i;

    // Reset logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 15; i = i + 1) begin
                rf[i] <= 32'b0;
            end
        end
        else if (we3) begin
            if (wa3 != 4'b1111) begin
                rf[wa3] <= wd3;
            end
        end
    end

    // Read logic
    assign rd1 = (ra1 == 4'b1111) ? r15 : rf[ra1];
    assign rd2 = (ra2 == 4'b1111) ? r15 : rf[ra2];

endmodule

module mux8_parm #(
