module gtx_tx_reset_controller(
input wire clk,
input wire ref_clk,
input wire powerup_channel,
output reg tx_running,
output reg txreset,
output reg txuserrdy,
output reg txpmareset,
output reg txpcsreset,
output reg pllpd,
output reg pllreset,
output reg plllocken,
input wire plllock,
output reg resetsel,
input wire txresetdone
);
reg [3:0] state = 4'h0;
reg [7:0] counter = 1'b0;
reg [7:0] ref_clk_counter = 1'b0;
reg ref_clk_detect_last = 1'b0;
reg ref_clk_detect = 1'b0;
reg ref_clk_detect_meta = 1'b0;
reg txresetdone_meta = 1'b0;
reg txresetdone_i = 1'b0;
  always @(posedge ref_clk) begin
    ref_clk_counter <= ref_clk_counter + 1;
  end
  always @(posedge clk) begin
    counter <= counter + 1;
    case(state)
    4'h0 : begin
      // reset state;
      txreset <= 1'b1;
      txuserrdy <= 1'b0;
      txpmareset <= 1'b0;
      txpcsreset <= 1'b0;
      pllpd <= 1'b1;
      pllreset <= 1'b1;
      plllocken <= 1'b0;
      resetsel <= 1'b0;
      state <= 4'h1;
    end
    4'h1 : begin
      // wait for reference clock
      counter <= {8{1'b0}};
      if(ref_clk_detect != ref_clk_detect_last) begin
        state <= 4'h2;
      end
    end
    4'h2 : begin
      // wait for 500ns
      // counter will set high bit after 128 cycles
      if(counter[(7)] == 1'b1) begin
        state <= 4'h3;
      end
    end
    4'h3 : begin
      // start up the PLL
      pllpd <= 1'b0;
      pllreset <= 1'b0;
      plllocken <= 1'b1;
      state <= 4'h4;
    end
    4'h4 : begin
      // Waiting for the PLL to lock
      if(plllock == 1'b1) begin
        state <= 4'h5;
      end
    end
    4'h5 : begin
      // Starting up the GTX
      txreset <= 1'b0;
      state <= 4'h6;
      counter <= {8{1'b0}};
    end
    4'h6 : begin
      // wait for 500ns
      // counter will set high bit after 128 cycles
      if(counter[(7)] == 1'b1) begin
        state <= 4'h7;
      end
    end
    4'h7 : begin
      txuserrdy <= 1'b1;
      if(txresetdone_i == 1'b1) begin
        state <= 4'h8;
      end
    end
    4'h8 : begin
      tx_running <= 1'b1;
    end
    default : begin
      // Monitoring for it to have started up;
      state <= 4'h0;
    end
    endcase
    if(powerup_channel == 1'b0) begin
      state <= 4'h0;
    end
    ref_clk_detect_last <= ref_clk_detect;
    ref_clk_detect <= ref_clk_detect_meta;
    ref_clk_detect_meta <= ref_clk_counter[(7)];
    txresetdone_i <= txresetdone_meta;
    txresetdone_meta <= txresetdone;
  end
endmodule

module sub_213(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

