module fp_rsft78(
input wire [78:1] inbus,
input wire [6:1] shift,
output wire [78:1] outbus
);
wire [78:1] levzip; wire [78:1] levone; wire [78:1] levtwo;
wire [78:1] levthr; wire [78:1] levfor; wire [78:1] levfiv;
wire [78:1] levsix;
  assign levzip = inbus;
  genvar k;
  generate for (k=1; k <= 77; k = k + 1) begin: gaa
      assign levone[k] = (levzip[k] &  ~(shift[1])) | (levzip[k + 1] & shift[1]);
  end
  endgenerate
  assign levone[78] = levzip[78] &  ~(shift[1]);
  genvar k;
  generate for (k=1; k <= 76; k = k + 1) begin: gba
      assign levtwo[k] = (levone[k] &  ~(shift[2])) | (levone[k + 2] & shift[2]);
  end
  endgenerate
  assign levtwo[77] = levone[77] &  ~(shift[2]);
  assign levtwo[78] = levone[78] &  ~(shift[2]);
  genvar k;
  generate for (k=1; k <= 74; k = k + 1) begin: gca
      assign levthr[k] = (levtwo[k] &  ~(shift[3])) | (levtwo[k + 4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=75; k <= 78; k = k + 1) begin: gcb
      assign levthr[k] = levtwo[k] &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 70; k = k + 1) begin: gda
      assign levfor[k] = (levthr[k] &  ~(shift[4])) | (levthr[k + 8] & shift[4]);
  end
  endgenerate
  genvar k;
  generate for (k=71; k <= 78; k = k + 1) begin: gdb
      assign levfor[k] = levthr[k] &  ~(shift[4]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 62; k = k + 1) begin: gea
      assign levfiv[k] = (levfor[k] &  ~(shift[5])) | (levfor[k + 16] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=63; k <= 78; k = k + 1) begin: geb
      assign levfiv[k] = levfor[k] &  ~(shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 46; k = k + 1) begin: gfa
      assign levsix[k] = (levfiv[k] &  ~(shift[6])) | (levfiv[k + 32] & shift[6]);
  end
  endgenerate
  genvar k;
  generate for (k=47; k <= 78; k = k + 1) begin: gfb
      assign levsix[k] = levfiv[k] &  ~(shift[6]);
  end
  endgenerate
  assign outbus = levsix;
endmodule

module SquareWave (
    input wire iClk,
    input wire isquareWave,
    input wire iRst_n,
    output wire oState_n
);

    parameter CRAZY_TIME = 45000;
    parameter START_TIME = 30000;

    reg rState;
    reg rState0, rState1;
    reg [15:0] rCnt;
    reg [15:0] rStartUpCnt;

    always @(posedge iClk or negedge iRst_n) begin
        if (!iRst_n) begin
            rState0 <= 1'b0;
            rState1 <= 1'b0;
            rCnt <= 16'd0;
            rState <= 1'b0;
            rStartUpCnt <= 16'd0;
        end else begin
            rState0 <= isquareWave;
            rState1 <= rState0;

            if (rStartUpCnt < START_TIME) begin
                rStartUpCnt <= rStartUpCnt + 1'b1;
                rState <= 1'b0;
            end else begin
                if (rState0 != rState1) begin
                    if (rCnt < CRAZY_TIME) begin
                        rCnt <= 16'd0;
                        rState <= 1'b0;
                    end
                end else begin
                    if (rCnt < CRAZY_TIME) begin
                        rCnt <= rCnt + 1'b1;
                    end else begin
                        rState <= 1'b1;
                    end
                end
            end
        end
    end

    assign oState_n = ~rState;

endmodule

