module ALU (
    input wire clk,
    input wire rst,
    input wire [15:0] A,
    input wire [15:0] B,
    input wire [4:0] Operation,
    output reg [15:0] out,
    output reg Zero
);

    // Operation codes
    parameter LOAD     = 5'b00000;
    parameter STORE    = 5'b00001;
    parameter JUMP     = 5'b00010;
    parameter BRANCH_Z = 5'b00011;
    parameter ADD      = 5'b00100;
    parameter SUB      = 5'b00101;
    parameter AND      = 5'b00110;
    parameter OR       = 5'b00111;
    parameter NOT      = 5'b01000;
    parameter MOVE     = 5'b01001;
    parameter NOP      = 5'b01010;
    parameter ADDI     = 5'b01011;
    parameter SUBI     = 5'b01100;
    parameter ANDI     = 5'b01101;
    parameter ORI      = 5'b01110;
    parameter WND0     = 5'b01111;
    parameter WND1     = 5'b10000;
    parameter WND2     = 5'b10001;
    parameter WND3     = 5'b10010;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out <= 16'b0;
            Zero <= 1'b0;
        end else begin
            case (Operation)
                BRANCH_Z: begin
                    Zero <= (A == B);
                end
                MOVE: begin
                    out <= B;
                end
                SUB: begin
                    out <= A - B;
                end
                AND: begin
                    out <= A & B;
                end
                OR: begin
                    out <= A | B;
                end
                NOT: begin
                    out <= ~B;
                end
                ADDI: begin
                    out <= B + A;
                end
                SUBI: begin
                    out <= B - A;
                end
                ANDI: begin
                    out <= B & A;
                end
                ORI: begin
                    out <= B | A;
                end
                default: begin
                    // No operation
                end
            endcase
        end
    end

endmodule

