    always @(posedge MCLK or posedge RESET_IN) begin
        if (RESET_IN) begin
            counter <= 26'd0;
            clk <= 1'b0;
        end else begin
            if (counter == 26'd49999999) begin
                counter <= 26'd0;
                clk <= ~clk;
