module DEDFF (
    input wire clk,
    input wire rst,
    input wire D0,
    input wire D1,
    output wire Q
);

reg pose_edge, neg_edge;
wire Q1, Q2;

// Positive edge-triggered process
always @(posedge clk or negedge rst) begin
    if (!rst)
        pose_edge <= 1'b0;
    else
        pose_edge <= Q1;
end

// Negative edge-triggered process
always @(negedge clk or negedge rst) begin
    if (!rst)
        neg_edge <= 1'b0;
    else
        neg_edge <= Q2;
end

// Combinational logic
assign Q1 = neg_edge ^ D0;
assign Q2 = pose_edge ^ D1;
assign Q = neg_edge ^ pose_edge;

endmodule

