module BinGray(
input wire [3:0] Code,
input wire Sel,
output reg [7:0] Seg,
output wire [3:0] Display
);
//Las señales embebidas se declaran aqui !!!!!!!!!!!!!!
wire [3:0] Gray;
wire [3:0] Bin;
wire [3:0] Dato;
  // Definicion de BinToGray
  // Binary to Gray conversion using Loops
  assign Gray[3] = Code[3];
  genvar i;
  generate for (i=2; i >= 0; i = i - 1) begin: for_loop
    assign Gray[i] = Code[i + 1] ^ Code[i];
  end
  endgenerate
  // Definicion de GrayToBin
  // Gray to Bin conversion using Loops
  assign Bin[3] = Code[3];
  genvar i;
  generate for (i=2; i >= 0; i = i - 1) begin: for_loop1
    assign Bin[i] = Bin[i + 1] ^ Code[i];
  end
  endgenerate
  // Definicion del multiplexor
  assign Dato = Sel == 1'b0 ? Gray : Bin;
  // Definicion del Decodificador Bin a 7 Segmentos
  // utilizando una declaracion concurrente.
  always @(Dato) begin
    //.gfedcba
    if(Dato == 4'h0) begin
      Seg <= 8'b11000000;
    end
    else if(Dato == 4'h1) begin
      Seg <= 8'b11111001;
    end
    else if(Dato == 4'h2) begin
      Seg <= 8'b10100100;
    end
    else if(Dato == 4'h3) begin
      Seg <= 8'b10110000;
    end
    else if(Dato == 4'h4) begin
      Seg <= 8'b10011001;
    end
    else if(Dato == 4'h5) begin
      Seg <= 8'b10010010;
    end
    else if(Dato == 4'h6) begin
      Seg <= 8'b10000010;
    end
    else if(Dato == 4'h7) begin
      Seg <= 8'b11111000;
    end
    else if(Dato == 4'h8) begin
      Seg <= 8'b10000000;
    end
    else if(Dato == 4'h9) begin
      Seg <= 8'b10010000;
    end
    else if(Dato == 4'hA) begin
      Seg <= 8'b10001000;
    end
    else if(Dato == 4'hB) begin
      Seg <= 8'b10000011;
    end
    else if(Dato == 4'hC) begin
      Seg <= 8'b11000110;
    end
    else if(Dato == 4'hD) begin
      Seg <= 8'b10100001;
    end
    else if(Dato == 4'hE) begin
      Seg <= 8'b10000110;
    end
    else begin
      Seg <= 8'b10001110;
    end
  end
  // Select Display
  assign Display = 4'b1110;
endmodule

