module SUBT(
input wire [7:0] A,
input wire [7:0] B,
output wire [7:0] F,
output wire [3:0] Flag
);
wire [7:0] c; wire [7:0] Bin; wire [7:0] S;
  assign Bin[0] = B[0] ^ 1'b1;
  assign Bin[1] = B[1] ^ 1'b1;
  assign Bin[2] = B[2] ^ 1'b1;
  assign Bin[3] = B[3] ^ 1'b1;
  assign Bin[4] = B[4] ^ 1'b1;
  assign Bin[5] = B[5] ^ 1'b1;
  assign Bin[6] = B[6] ^ 1'b1;
  assign Bin[7] = B[7] ^ 1'b1;
  fulladder A0(
      A[0],
    Bin[0],
    1'b1,
    S[0],
    c[0]);
  fulladder A1(
      A[1],
    Bin[1],
    c[0],
    S[1],
    c[1]);
  fulladder A2(
      A[2],
    Bin[2],
    c[1],
    S[2],
    c[2]);
  fulladder A3(
      A[3],
    Bin[3],
    c[2],
    S[3],
    c[3]);
  fulladder A4(
      A[4],
    Bin[4],
    c[3],
    S[4],
    c[4]);
  fulladder A5(
      A[5],
    Bin[5],
    c[4],
    S[5],
    c[5]);
  fulladder A6(
      A[6],
    Bin[6],
    c[5],
    S[6],
    c[6]);
  fulladder A7(
      A[7],
    Bin[7],
    c[6],
    S[7],
    c[7]);
  assign Flag[3] =  ~(S[7] | S[6] | S[5] | S[4] | S[3] | S[2] | S[1] | S[0]);
  assign Flag[2] = c[7] ^ c[6];
  assign Flag[1] = c[7];
  assign Flag[0] = S[7];
  assign F = S;
endmodule

