module Ctr (
    input wire [5:0] opCode,
    input wire reset,
    output reg regDst,
    output reg aluSrc,
    output reg memToReg,
    output reg regWrite,
    output reg memRead,
    output reg memWrite,
    output reg branch,
    output reg [1:0] aluOp,
    output reg jump
);

always @(*) begin
    if (reset) begin
        regDst = 0;
        aluSrc = 0;
        memToReg = 0;
        regWrite = 0;
        memRead = 0;
        memWrite = 0;
        branch = 0;
        aluOp = 2'b00;
        jump = 0;
    end else begin
        case (opCode)
            6'b000010: begin // Jump
                regDst = 0;
                aluSrc = 0;
                memToReg = 0;
                regWrite = 0;
                memRead = 0;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b00;
                jump = 1;
            end
            6'b000000: begin // R-type
                regDst = 1;
                aluSrc = 0;
                memToReg = 0;
                regWrite = 1;
                memRead = 0;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b10;
                jump = 0;
            end
            6'b100011: begin // Load word
                regDst = 0;
                aluSrc = 1;
                memToReg = 1;
                regWrite = 1;
                memRead = 1;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b00;
                jump = 0;
            end
            6'b101011: begin // Store word
                regDst = 0;
                aluSrc = 1;
                memToReg = 0;
                regWrite = 0;
                memRead = 0;
                memWrite = 1;
                branch = 0;
                aluOp = 2'b00;
                jump = 0;
            end
            6'b000100: begin // Branch on equal
                regDst = 0;
                aluSrc = 0;
                memToReg = 0;
                regWrite = 0;
                memRead = 0;
                memWrite = 0;
                branch = 1;
                aluOp = 2'b01;
                jump = 0;
            end
            default: begin // Unsupported opCode
                regDst = 0;
                aluSrc = 0;
                memToReg = 0;
                regWrite = 0;
                memRead = 0;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b00;
                jump = 0;
            end
        endcase
    end
end

endmodule

module virtual_top_level(
input wire clk,
input wire reset,
input wire [7:0] pb,
input wire [7:0] sw,
output wire [7:0] led,
output reg [7:0] sseg_anode,
output wire [7:0] sseg_common_cathode
);
parameter DIVIDER1HZ = 100000000;
parameter DIVIDER5HZ = 20000000;
parameter DIVIDER10HZ = 10000000;
parameter DIVIDER100HZ = 1000000;
reg [31:0] divider_output1hz; reg [31:0] divider_output5hz; reg [31:0] divider_output10hz; reg [31:0] divider_output100hz;
wire onehz_signal; wire fivehz_signal; wire tenhz_signal; wire onehundredhz_signal;
reg update_count_output;
reg [7:0] counter_output;
wire counter_enable; wire counter_reset;
wire [1:0] sel;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      divider_output1hz <= DIVIDER1HZ;
      divider_output5hz <= DIVIDER5HZ;
      divider_output10hz <= DIVIDER10HZ;
      divider_output100hz <= DIVIDER100HZ;
    end else begin
      if(divider_output1hz == 0) begin
        divider_output1hz <= DIVIDER1HZ;
      end
      else begin
        divider_output1hz <= divider_output1hz - 1;
      end
      if(divider_output5hz == 0) begin
        divider_output5hz <= DIVIDER5HZ;
      end
      else begin
        divider_output5hz <= divider_output5hz - 1;
      end
      if(divider_output10hz == 0) begin
        divider_output10hz <= DIVIDER10HZ;
      end
      else begin
        divider_output10hz <= divider_output10hz - 1;
      end
      if(divider_output100hz == 0) begin
        divider_output100hz <= DIVIDER100HZ;
      end
      else begin
        divider_output100hz <= divider_output100hz - 1;
      end
    end
  end
  assign onehz_signal = divider_output1hz == 0 ? 1'b1 : 1'b0;
  assign fivehz_signal = divider_output5hz == 0 ? 1'b1 : 1'b0;
  assign tenhz_signal = divider_output10hz == 0 ? 1'b1 : 1'b0;
  assign onehundredhz_signal = divider_output100hz == 0 ? 1'b1 : 1'b0;
  //mux the count out enable input different frequncy values
  always @(*) begin
    case(sw[7:6])
      2'b00 : update_count_output <= onehz_signal;
      2'b01 : update_count_output <= fivehz_signal;
      2'b10 : update_count_output <= tenhz_signal;
      2'b11 : update_count_output <= onehundredhz_signal;
    endcase
  end
  assign counter_enable = sw[0];
  assign counter_reset = pb[1];
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      counter_output <= {8{1'b0}};
    end else begin
      if(counter_reset == 1'b1) begin
        counter_output <= {8{1'b0}};
      end
      else if(counter_enable == 1'b1 && update_count_output == 1'b1) begin
        //100 hz updateupdate_count_output
        counter_output <= counter_output + 1;
      end
    end
  end
  assign led[7:0] = counter_output;
  assign sseg_common_cathode = {8{1'b0}};
  assign sseg_anode[7] = 1'b0;
  // dot point
  always @(*) begin
    case(counter_output[3:0])
  //"gfedcba" segments
      4'b0000 : sseg_anode[6:0] <= 7'b0111111;
  //0
      4'b0001 : sseg_anode[6:0] <= 7'b0000110;
  //1
      4'b0010 : sseg_anode[6:0] <= 7'b1011011;
  //2
      4'b0011 : sseg_anode[6:0] <= 7'b1001111;
