      4'b0101 : sseg_anode[6:0] <= 7'b1101101;
  //5
      4'b0110 : sseg_anode[6:0] <= 7'b1111101;
  //6
      4'b0111 : sseg_anode[6:0] <= 7'b0000111;
  //7
      4'b1000 : sseg_anode[6:0] <= 7'b1111111;
  //8
      4'b1001 : sseg_anode[6:0] <= 7'b1101111;
  //9
      4'b1010 : sseg_anode[6:0] <= 7'b1110111;
  //a
      4'b1011 : sseg_anode[6:0] <= 7'b1111100;
  //b
      4'b1100 : sseg_anode[6:0] <= 7'b0111001;
  //c
      4'b1101 : sseg_anode[6:0] <= 7'b1011110;
  //d
      4'b1110 : sseg_anode[6:0] <= 7'b1111001;
