module interceptor(
input wire [17:0] ins_rom_in,
input wire [17:0] ins_ram_in,
input wire [7:0] data_in,
input wire clk,
input wire [9:0] address_in,
output reg [9:0] address_out,
output reg [17:0] ins_out,
output reg [17:0] ins_ram_prog,
output reg ram_we,
output reg ram_oe
);
reg cnt_inc_i = 1'b0;
reg cnt_rst_i = 1'b0;
reg ins_cnt_inc_i = 1'b0;
reg [2:0] cnt = 1'b0;
reg [10:0] ins_cnt = 1'b0;
reg hex_en_i[0:4] = 1'b0;
reg [3:0] ins_hex_i[0:4] = 1'b0;
parameter [2:0]
  st_int = 0,
  st_get_input = 1,
  st_write_ins = 2,
  st_trans = 3,
  st_end = 4;
reg [2:0] ps; reg [2:0] ns;
  always @(posedge clk) begin
    for (i=0; i <= 4; i = i + 1) begin
      if((hex_en_i[i] == 1'b1)) begin
        ins_hex_i[i] <= data_in[3:0];
      end
    end
    if((cnt_inc_i == 1'b1)) begin
      cnt <= cnt + 1;
    end
    else if((cnt_rst_i == 1'b1)) begin
      cnt <= 3'b000;
    end
    if((ins_cnt_inc_i == 1'b1)) begin
      ins_cnt <= ins_cnt + 1;
    end
    ps <= ns;
  end
  always @(ps, data_in, ins_rom_in, ins_ram_in, ins_hex_i, cnt, ins_cnt, address_in) begin
    ins_out <= ins_rom_in;
    ram_we <= 1'b0;
    ram_oe <= 1'b0;
    ins_ram_prog <= {18{1'b0}};
    hex_en_i <= 5'b00000;
    cnt_inc_i <= 1'b0;
    cnt_rst_i <= 1'b0;
    ins_cnt_inc_i <= 1'b0;
    address_out <= address_in;
    case(ps)
        // wait until the special instruction is sent
    // this will happen during the fetch cycle
    st_int : begin
      ns <= st_int;
      if((ins_rom_in[17:13] == 5'b01111)) begin
        // new LDPR special opcode
        ins_out <= {5'b11010,ins_rom_in[12:0]};
        ns <= st_get_input;
      end
      if((ins_cnt == 11'b10000000000)) begin
        ns <= st_trans;
      end
      // get the data and put it into the proper place
    end
    st_get_input : begin
      ns <= st_int;
      // we still need to assert the OUT ins instead of the LDPR
      // each instruction needs TWO clock cycles
      ins_out <= {5'b11010,ins_rom_in[12:0]};
      if((cnt <= 3'b011)) begin
        hex_en_i[cnt] <= 1'b1;
        cnt_inc_i <= 1'b1;
      end
      else begin
        hex_en_i[4] <= 1'b1;
        cnt_rst_i <= 1'b1;
        ns <= st_write_ins;
      end
      // once we have the 3 parts of the ins, write it to the RAM
      // fetch cycle again (thus we CANNOT have consecutive LDPR instructions)
      // ideally it'll take a long time for each byte to be ready anyway
    end
    st_write_ins : begin
      ns <= st_int;
      ram_we <= 1'b1;
      ram_oe <= 1'b1;
      address_out <= ins_cnt[9:0];
      ins_ram_prog <= {ins_hex_i[4][1:0],ins_hex_i[3],ins_hex_i[2],ins_hex_i[1],ins_hex_i[0]};
      ins_cnt_inc_i <= 1'b1;
      if((ins_cnt == 11'b10000000000)) begin
        //1024 increments
        ns <= st_trans;
      end
      // steps necessary to transfer control to RAM:
      // reset pc and sp to 0
    end
    st_trans : begin
      if(((cnt == 3'b000) || (cnt == 3'b001))) begin
        // the WSP ins, to reset sp to 0
        // we have to hold this for 2 cycles
        ins_out <= {5'b01010,5'b10000,8'b00000000};
        cnt_inc_i <= 1'b1;
        ns <= st_trans;
      end
      else if((cnt == 3'b010)) begin
        // the BRN ins, to reset pc to 0
        ins_out <= {5'b00100,10'b0000000000,3'b000};
        cnt_inc_i <= 1'b1;
        ns <= st_trans;
      end
      else begin
        // keep asserting BRN 0x00, we need to get to st_end
        ins_out <= {5'b00100,10'b0000000000,3'b000};
        ns <= st_end;
      end
      // we are done. only use prog_ram now. 
      // note we can't get out of this state
    end
    st_end : begin
      ram_oe <= 1'b1;
      ins_out <= ins_ram_in;
      ns <= st_end;
      // to prevent latches
    end
    default : begin
      ns <= st_int;
      if((ins_cnt == 11'b10000000000)) begin
        ns <= st_end;
      end
    end
    endcase
  end
endmodule

