wire [31:0] sigOutAdd;
wire sigOutAddCarry;
wire [63:0] sigOutRegShift;
  SM2 stateMachine(
      clk,
    reset,
    sigSelReg);
  mux2to1 mux(
      sigOutRegShift[0],
