input wire [31:0] in0,
output wire [31:0] sum
);
wire [32:0] temp_c;
  genvar i;
  generate for (i=0; i <= 31; i = i + 1) begin: add
      //generate 32 1-bit adders for add32 entity
    add1 add32(
          .in1(in1[i]),
      .in0(in0[i]),
      .cin(temp_c[i]),
      // Cin will be previous value temp signal 
      .cout(temp_c[i + 1]),
      // cout will feed into cin
      .sum(sum[i]));
  end
  endgenerate
  assign temp_c[0] = 1'b0;
    // Set cin to first adder to 0. Leaving it blank will result in an 'X' for sum(0)
endmodule

module btn_control(
input wire clk,
input wire rst,
input wire [3:0] btn_bus,
output wire [3:0] output_bus
);
reg [3:0] stage1 = 4'b0000; reg [3:0] stage2 = 4'b0000;
reg lock = 1'b0;
  //debounce the input buttons, and only allow one to pulse per press
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      stage1 <= 4'b0000;
      stage2 <= 4'b0000;
      lock <= 1'b0;
    end else begin
      stage1 <= btn_bus;
      stage2 <= stage1;
      lock <= stage2[3] | stage2[2] | stage2[1] | stage2[0];
    end
  end
  assign output_bus[3] = stage1[3] & stage2[3] & ( ~lock);
  assign output_bus[2] = stage1[2] & stage2[2] & ( ~lock);
  assign output_bus[1] = stage1[1] & stage2[1] & ( ~lock);
  assign output_bus[0] = stage1[0] & stage2[0] & ( ~lock);
endmodule

