module UART_REG (
    input wire CLK,
    input wire RESET,
    input wire [7:0] data_inH,
    input wire [7:0] data_inL,
    input wire [7:0] SRCH,
    input wire [7:0] SRCL,
    input wire [7:0] DSTH,
    input wire [7:0] DSTL,
    input wire [7:0] ALU_OP,
    input wire finish_pluse,
    input wire io_write_dp,
    output reg [7:0] data_inH_in,
    output reg [7:0] data_inL_in,
    output reg [7:0] SRCH_in,
    output reg [7:0] SRCL_in,
    output reg [7:0] DSTH_in,
    output reg [7:0] DSTL_in,
    output reg [7:0] ALU_OP_in,
    output reg ready
);

    reg [1:0] FLAG;

    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            data_inH_in <= 8'b0;
            data_inL_in <= 8'b0;
            SRCH_in <= 8'b0;
            SRCL_in <= 8'b0;
            DSTH_in <= 8'b0;
            DSTL_in <= 8'b0;
            ALU_OP_in <= 8'b0;
            ready <= 1'b0;
            FLAG <= 2'b00;
        end else begin
            if (finish_pluse) begin
                SRCH_in <= SRCH;
                SRCL_in <= SRCL;
                DSTH_in <= DSTH;
                DSTL_in <= DSTL;
                ALU_OP_in <= ALU_OP;
                FLAG[0] <= 1'b1;
            end

            if (io_write_dp) begin
                data_inH_in <= data_inH;
                data_inL_in <= data_inL;
                FLAG[1] <= 1'b1;
            end

            if (FLAG == 2'b11) begin
                ready <= 1'b1;
                FLAG <= 2'b00;
            end else begin
                ready <= 1'b0;
            end
        end
    end

endmodule

module frequency_divider_generic(
input wire clk_in,
input wire reset,
output reg output
);
parameter [31:0] divide_by;
reg [31:0] count = 0;
  always @(posedge clk_in, posedge reset) begin
    if(reset == 1'b0) begin
      //asynchronous, active low reset
      output <= 1'b0;
      count <= 0;
    end else begin
      count <= count + 1;
      if((count == (divide_by - 1))) begin
        output <= 1'b1;
        count <= 0;
      end
      else begin
        output <= 1'b0;
      end
    end
  end
endmodule

