module level_shift_test01(
input wire pi_base_clk,
input wire [9:0] pi_sw,
input wire [3:0] pi_btn_n,
output reg [9:0] po_led_r,
output reg [7:0] po_led_g,
inout reg [7:0] pio_gpio0,
inout reg [7:0] pio_gpio1
);
//slow down button update timing.
parameter FREQ_DEVIDE = 1000000;
reg [31:0] reg_cnt_devider;
reg [7:0] reg_8bit_cnt;
wire wr_rst_n;
wire wr_direction;
wire wr_dvd;
  assign wr_rst_n = pi_btn_n[0];
  assign wr_direction = pi_sw[9];
  assign wr_dvd = pi_sw[8];
  always @(posedge wr_rst_n, posedge pi_base_clk) begin
    if((wr_rst_n == 1'b0)) begin
      pio_gpio0 <= {8{1'bZ}};
      pio_gpio1 <= {8{1'bZ}};
      po_led_r <= {10{1'b0}};
      po_led_g <= {8{1'b0}};
    end else begin
      if((wr_direction == 1'b0)) begin
        //case off = cp gpio 1 to 0
        pio_gpio0 <= {8{1'bZ}};
        pio_gpio1 <= pi_sw[7:0];
        po_led_r <= pi_sw;
        po_led_g <= pio_gpio0;
      end
      else begin
        //on = cp gpio 0 to 1
        pio_gpio0 <= reg_8bit_cnt;
        pio_gpio1 <= {8{1'bZ}};
        po_led_r[7:0] <= pio_gpio1;
        po_led_r[9:8] <= pi_sw[9:8];
        po_led_g <= reg_8bit_cnt;
      end
    end
  end
  //key3 button proc.
  always @(posedge wr_rst_n, posedge pi_base_clk) begin
    if((wr_rst_n == 1'b0)) begin
      reg_8bit_cnt <= {8{1'b0}};
    end else begin
      if((wr_dvd == 1'b1)) begin
        //slow down count up
        if((pi_btn_n[3] == 1'b0 && reg_cnt_devider == 0)) begin
          reg_8bit_cnt <= reg_8bit_cnt + 1;
        end
      end
      else begin
        //clock speed count up.
        if((pi_btn_n[3] == 1'b0)) begin
          reg_8bit_cnt <= reg_8bit_cnt + 1;
        end
      end
    end
  end
  //
  always @(posedge wr_rst_n, posedge pi_base_clk) begin
    if((wr_rst_n == 1'b0)) begin
      reg_cnt_devider <= 0;
    end else begin
      reg_cnt_devider <= reg_cnt_devider + 1;
    end
  end
endmodule

module ddu (
    input wire i_clk,
    input wire i_rst,
    input wire i_inc,
    input wire i_dec,
    input wire i_cont,
    input wire i_step,
    output reg [7:0] o_addr,
    output reg o_run
);

reg r_operated_inc, r_operated_dec;
reg r_run_enable;

always @(posedge i_clk or posedge i_rst) begin
    if (i_rst) begin
        o_addr <= 8'b0;
        r_operated_inc <= 1'b0;
        r_operated_dec <= 1'b0;
    end else begin
        if (i_inc && !r_operated_inc) begin
            o_addr <= o_addr + 1'b1;
            r_operated_inc <= 1'b1;
        end else if (i_dec && !r_operated_dec) begin
            o_addr <= o_addr - 1'b1;
            r_operated_dec <= 1'b1;
        end else begin
            r_operated_inc <= 1'b0;
            r_operated_dec <= 1'b0;
        end
    end
end

always @(posedge i_clk or posedge i_rst) begin
    if (i_rst) begin
        o_run <= 1'b0;
        r_run_enable <= 1'b0;
    end else begin
        if (i_cont) begin
            o_run <= 1'b1;
            r_run_enable <= 1'b0;
        end else if (i_step) begin
            if (!r_run_enable) begin
                o_run <= 1'b1;
                r_run_enable <= 1'b1;
            end else begin
                o_run <= 1'b0;
            end
        end else begin
            o_run <= 1'b0;
            r_run_enable <= 1'b0;
        end
    end
end

endmodule

