);
// opcode
// pc opcode to be filtered
// signals to be tested
// pc opcode after filtering
// no internal signals
  // design implementation
  always @(opcode, pc_op, test, carry, overflow) begin
    if(opcode == 2'b00) begin
      pc_op_out <= pc_op;
    end
    else if(opcode == 2'b01) begin
      if(test == 1'b1) begin
        pc_op_out <= pc_op;
      end
      else begin
        pc_op_out <= 3'b000;
      end
    end
    else if(opcode == 2'b10) begin
      if(carry == 1'b1) begin
        pc_op_out <= pc_op;
      end
      else begin
        pc_op_out <= 3'b000;
      end
    end
    else if(opcode == 2'b11) begin
      if(overflow == 1'b1) begin
        pc_op_out <= pc_op;
