module fp_invsqr_est(
input wire sysclk,
input wire reset,
input wire enable,
input wire [19:1] radicand,
output wire [18:1] invroot
);
parameter [31:0] synthesize=0;
// 0 = behavioral, 1 = syntheziable
wire [9:1] zerovec;
wire [9:1] one; wire [9:1] two;
reg [9:1] oneaddff; reg [9:1] zipaddff;
reg [9:1] twodelff[2:1];
wire [11:1] onelut; reg [11:1] onelutff;
wire [20:1] ziplut; reg [20:1] ziplutff;
reg [20:1] ziplutdelff[2:1];
wire [11:1] onetwo;
reg [20:1] invrootff;
  genvar k;
  generate for (k=1; k <= 9; k = k + 1) begin: gza
      assign zerovec[k] = 1'b0;
  end
  endgenerate
  assign one = radicand[18:10];
  assign two = radicand[9:1];
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 9; k = k + 1) begin
        oneaddff[k] <= 1'b0;
        zipaddff[k] <= 1'b0;
      end
      for (k=1; k <= 2; k = k + 1) begin
        for (j=1; j <= 9; j = j + 1) begin
          twodelff[k][j] <= 1'b0;
        end
      end
      for (k=1; k <= 11; k = k + 1) begin
        onelutff[k] <= 1'b0;
      end
      for (k=1; k <= 20; k = k + 1) begin
        ziplutff[k] <= 1'b0;
      end
      for (k=1; k <= 2; k = k + 1) begin
        for (j=1; j <= 20; j = j + 1) begin
          ziplutdelff[k][j] <= 1'b0;
        end
      end
      for (k=1; k <= 18; k = k + 1) begin
        invrootff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        oneaddff <= one;
        zipaddff <= one;
        twodelff[1][9:1] <= two;
        twodelff[2][9:1] <= twodelff[1][9:1];
        onelutff <= onelut;
        ziplutff <= ziplut;
        ziplutdelff[1][20:1] <= ziplutff;
        ziplutdelff[2][20:1] <= ziplutdelff[1][20:1];
        invrootff <= ziplutdelff[2][20:1] - ({zerovec[9:1],onetwo});
      end
    end
  end
  fp_invsqr_lut1 upper(
      .add(oneaddff),
    .data(onelut));
  fp_invsqr_lut0 lower(
      .add(zipaddff),
    .data(ziplut));
  fp_fxmul #(
      .widthaa(11),
    .widthbb(9),
    .widthcc(11),
    .pipes(2))
  mulcore(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .dataaa(onelutff),
    .databb(twodelff[2][9:1]),
    .result(onetwo));
  //**************
  //*** OUTPUT ***
  //**************
  assign invroot = invrootff[20:3];
endmodule

