module pipe (
    input wire clk,
    input wire n_rst,
    input wire [3:0] a,
    input wire [3:0] b,
    input wire [3:0] c,
    output reg [3:0] q,
    output reg [3:0] q_pipe
);

    reg [3:0] q_a, q_b, q_c;
    reg [3:0] q_ab, q_cc;

    always @(posedge clk or negedge n_rst) begin
        if (~n_rst) begin
            q_a <= 4'b0;
            q_b <= 4'b0;
            q_c <= 4'b0;
            q_ab <= 4'b0;
            q_cc <= 4'b0;
            q <= 4'b0;
            q_pipe <= 4'b0;
        end else begin
            // Stage 1: Register inputs
            q_a <= a;
            q_b <= b;
            q_c <= c;

            // Stage 2: Compute sum and register c again
            q_ab <= q_a + q_b;
            q_cc <= q_c;

            // Stage 3: Compute final results
            q <= (a + b) ^ c;
            q_pipe <= q_ab ^ q_cc;
        end
    end

endmodule

module fsm_1bit (
    input wire clk,
    input wire a,
    input wire reset,
    output reg out1,
    output reg out2
);

    // State register
    reg state, n_state;

    // State register logic
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= 1'b0;
        else
            state <= n_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            1'b0: n_state = a ? 1'b1 : 1'b0;
            1'b1: n_state = a ? 1'b1 : 1'b0;
            default: n_state = 1'b0;
        endcase
    end

    // Output logic
    always @(*) begin
        case (state)
            1'b0: begin
                out1 = 1'b1;
                out2 = 1'b0;
            end
            1'b1: begin
                out1 = 1'b0;
                out2 = 1'b1;
            end
            default: begin
                out1 = 1'b0;
                out2 = 1'b0;
            end
        endcase
    end

endmodule

