module seg_scan (
    input wire clk,
    input wire rst_n,
    input wire [7:0] seg_data_0,
    input wire [7:0] seg_data_1,
    input wire [7:0] seg_data_2,
    input wire [7:0] seg_data_3,
    input wire [7:0] seg_data_4,
    input wire [7:0] seg_data_5,
    output reg [5:0] seg_sel,
    output reg [7:0] seg_data
);

    // Parameters
    parameter SCAN_FREQ = 200;
    parameter CLK_FREQ = 50_000_000;
    parameter SCAN_COUNT = CLK_FREQ / (SCAN_FREQ * 6) - 1;

    // Internal registers
    reg [31:0] scan_timer;
    reg [3:0] scan_sel;

    // Main logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            scan_timer <= 32'd0;
            scan_sel <= 4'd0;
            seg_sel <= 6'b111111;
            seg_data <= 8'hff;
        end else begin
            if (scan_timer == SCAN_COUNT) begin
                scan_timer <= 32'd0;
                scan_sel <= (scan_sel == 4'd5) ? 4'd0 : scan_sel + 1'b1;
            end else begin
                scan_timer <= scan_timer + 1'b1;
            end

            case (scan_sel)
                4'd0: begin
                    seg_sel <= 6'b111110;
                    seg_data <= seg_data_0;
                end
                4'd1: begin
                    seg_sel <= 6'b111101;
                    seg_data <= seg_data_1;
                end
                4'd2: begin
                    seg_sel <= 6'b111011;
                    seg_data <= seg_data_2;
                end
                4'd3: begin
                    seg_sel <= 6'b110111;
                    seg_data <= seg_data_3;
                end
                4'd4: begin
                    seg_sel <= 6'b101111;
                    seg_data <= seg_data_4;
                end
                4'd5: begin
                    seg_sel <= 6'b011111;
                    seg_data <= seg_data_5;
                end
                default: begin
                    seg_sel <= 6'b111111;
                    seg_data <= 8'hff;
                end
            endcase
        end
    end

endmodule

