module exttuner (
    input wire clk,
    input wire auto_tune,
    input wire ATU_Status,
    input wire mox_in,
    output wire ATU_Start,
    output wire mox_out
);

    parameter PS_init = 17'd100000;  // Clock divider for 1ms timing
    parameter TuneDelay = 8'd100;    // 100ms delay
    parameter TuneWidth = 8'd50;     // 50ms tuning pulse width
    parameter LDetectLimit = 8'd200; // 200ms lower detect limit
    parameter HDetectLimit = 8'd250; // 250ms higher detect limit

    reg [16:0] ps;
    wire ps1ms;
    reg [3:0] state;
    reg [7:0] ms_count;
    reg tune, mox_inhibit;

    // Clock division for 1ms timing
    always @(posedge clk) begin
        if (ps == PS_init - 1)
            ps <= 0;
        else
            ps <= ps + 1;
    end

    assign ps1ms = (ps == PS_init - 1);

    // State machine and timing control
    always @(posedge clk) begin
        if (!auto_tune) begin
            state <= 0;
            ms_count <= 0;
            tune <= 0;
            mox_inhibit <= 0;
        end else begin
            if (ps1ms) begin
                case (state)
                    0: begin
                        state <= 1;
                        ms_count <= 0;
                        mox_inhibit <= 1;
                    end
                    1: begin
                        if (ms_count == TuneDelay - 1) begin
                            state <= 2;
                            ms_count <= 0;
                            tune <= 1;
                        end else
                            ms_count <= ms_count + 1;
                    end
                    2: begin
                        if (ms_count == TuneWidth - 1) begin
                            state <= 3;
                            ms_count <= 0;
                            tune <= 0;
                        end else
                            ms_count <= ms_count + 1;
                    end
                    3: begin
                        if (ATU_Status)
                            state <= 5;
                        else if (ms_count == LDetectLimit - 1)
                            state <= 4;
                        else
                            ms_count <= ms_count + 1;
                    end
                    4: begin
                        if (ATU_Status || ms_count == HDetectLimit - 1)
                            state <= 5;
                        else
                            ms_count <= ms_count + 1;
                    end
                    5: begin
                        mox_inhibit <= 0;
                        state <= 0;
                    end
                    default: state <= 0;
                endcase
            end
        end
    end

    // Output generation
    assign ATU_Start = tune;
    assign mox_out = mox_in & ~mox_inhibit;

endmodule

module debouncer(
    input wire clk,
    input wire butt,
    output reg pulse
);

    reg [24:0] count;
    reg pulso;
    wire isUp;

    assign isUp = count[24];

    always @(posedge clk) begin
        if (butt == 1'b1) begin
            if (count < 25'd2000)
                count <= count + 1'b1;
        end else begin
            count <= 25'd0;
        end
    end

    always @(posedge clk) begin
        if (butt == 1'b0) begin
            pulso <= 1'b0;
        end else if (count == 25'd2000) begin
            pulso <= 1'b1;
        end
    end

    always @(posedge clk) begin
        pulse <= pulso;
    end

endmodule

