module EPROC_IN16(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
input wire ENA,
input wire [1:0] ENCODING,
input wire [15:0] EDATA_IN,
output wire [9:0] DATA_OUT,
output wire DATA_RDY,
output wire busyOut
);
parameter do_generate=true;
parameter includeNoEncodingCase=true;
parameter zeros10array = 1'b0;
wire [9:0] DATA_OUT_direct; wire [9:0] DATA_OUT_8b10b_case; wire [9:0] DATA_OUT_HDLC_case; wire [9:0] DATA_OUT_s;
wire DATA_RDY_direct; wire DATA_RDY_8b10b_case; wire DATA_RDY_HDLC_case; wire DATA_RDY_sig;
wire RESTART_sig; wire rst_case00; wire rst_case01;  //-
  generate if (do_generate == true) begin: gen_enabled
      assign RESTART_sig = rst | ( ~ENA);
    // comes from clk40 domain 
    //-----------------------------------------------------------------------------------------
    // ENCODING case "00": direct data, no delimeter...
    //-----------------------------------------------------------------------------------------
    generate if (includeNoEncodingCase == true) begin: direct_data_enabled
          assign rst_case00 = RESTART_sig | (ENCODING[1] | ENCODING[0]);
      EPROC_IN16_direct EPROC_IN16_direct_inst(
              .bitCLKx4(bitCLKx4),
        .rst(rst_case00),
        .edataIN(EDATA_IN),
        .dataOUT(DATA_OUT_direct),
        .dataOUTrdy(DATA_RDY_direct));
    end
    endgenerate
    //
    generate if (includeNoEncodingCase == false) begin: direct_data_disabled
          assign DATA_RDY_direct = 1'b0;
      assign DATA_OUT_direct = {10{1'b0}};
    end
    endgenerate
    //
    //-----------------------------------------------------------------------------------------
    // ENCODING case "01": DEC8b10b
    //-----------------------------------------------------------------------------------------
    assign rst_case01 = RESTART_sig | (ENCODING[1] | ( ~ENCODING[0]));
    //
    EPROC_IN16_DEC8b10b EPROC_IN16_DEC8b10b_inst(
          .bitCLK(bitCLK),
      .bitCLKx2(bitCLKx2),
      .bitCLKx4(bitCLKx4),
      .rst(rst_case01),
      .edataIN(EDATA_IN),
      .dataOUT(DATA_OUT_8b10b_case),
      .dataOUTrdy(DATA_RDY_8b10b_case),
      .busyOut(busyOut));
    //-----------------------------------------------------------------------------------------
    // ENCODING case "10": HDLC
    //-----------------------------------------------------------------------------------------
    // TBD
    assign DATA_OUT_HDLC_case = {10{1'b0}};
    assign DATA_RDY_HDLC_case = 1'b0;
    //-----------------------------------------------------------------------------------------
    // output data/rdy according to the encoding settings
    //-----------------------------------------------------------------------------------------
    MUX4_Nbit #(
          .N(10))
    DATA_OUT_MUX4_10bit(
          .data0(DATA_OUT_direct),
      .data1(DATA_OUT_8b10b_case),
      .data2(DATA_OUT_HDLC_case),
      .data3(zeros10array),
      .sel(ENCODING),
      .data_out(DATA_OUT_s));
    MUX4 DATA_RDY_MUX4(
          .data0(DATA_RDY_direct),
      .data1(DATA_RDY_8b10b_case),
      .data2(DATA_RDY_HDLC_case),
      .data3(1'b0),
      .sel(ENCODING),
      .data_out(DATA_RDY_sig));
    assign DATA_RDY = DATA_RDY_sig;
    assign DATA_OUT = DATA_OUT_s;
        //------------------
  end
  endgenerate
  //
  //
  generate if (do_generate == false) begin: gen_disabled
      assign DATA_OUT = {10{1'b0}};
    assign DATA_RDY = 1'b0;
    assign busyOut = 1'b0;
  end
  endgenerate
endmodule

