module signalInput (
    input wire sysclk,
    input wire resetb,
    input wire [1:0] testmode,
    output reg sigIn
);

    reg [20:0] state;
    reg [20:0] divide;

    always @(*) begin
        case (testmode)
            2'b00: divide = 21'd16000;
            2'b01: divide = 21'd8000;
            2'b10: divide = 21'd1000000;
            2'b11: divide = 21'd4000;
        endcase
    end

    always @(posedge sysclk or negedge resetb) begin
        if (!resetb) begin
            sigIn <= 1'b0;
            state <= 21'd2;
        end else begin
            if (state == 21'd2) begin
                sigIn <= ~sigIn;
                state <= 21'd4;
            end else if (state >= divide) begin
                state <= 21'd2;
            end else begin
