module EPROC_IN2_direct(
input wire bitCLK,
input wire bitCLKx4,
input wire rst,
input wire [1:0] edataIN,
output wire [9:0] dataOUT,
output wire dataOUTrdy
);
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
reg [9:0] word10b = 10'b1100000000;  // comma
reg [7:0] word8b = 1'b0;
reg [1:0] inpcount = 1'b0;
reg word8bRdy = 1'b0; reg word10bRdy = 1'b0;
  //-----------------------------------------------------------------------------------------
  // input counter 0 to 3
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK, posedge rst) begin
    if(rst == 1'b1) begin
      inpcount <= {2{1'b0}};
    end else begin
      inpcount <= inpcount + 1;
    end
  end
  //-----------------------------------------------------------------------------------------
  // input mapping
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    case(inpcount)
    2'b00 : begin
      word8b[1:0] <= edataIN;
    end
    2'b01 : begin
      word8b[3:2] <= edataIN;
    end
    2'b10 : begin
      word8b[5:4] <= edataIN;
    end
    2'b11 : begin
      word8b[7:6] <= edataIN;
    end
    default : begin
    end
    endcase
  end
  //-----------------------------------------------------------------------------------------
  // output (code = "00" = data)
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(inpcount == 2'b11) begin
      word8bRdy <= 1'b1;
    end
    else begin
      word8bRdy <= 1'b0;
    end
  end
  //
  always @(posedge bitCLK) begin
    if(word8bRdy == 1'b1) begin
      word10b <= {2'b00,word8b};
      // data
      word10bRdy <= 1'b1;
    end
    else begin
      word10bRdy <= 1'b0;
    end
  end
  assign dataOUT = word10b;
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(1))
  dataOUTrdy_pulse(
      bitCLKx4,
    word10bRdy,
    dataOUTrdy);
endmodule

module opcode_fetch(
input wire CLK_I,
input wire T2,
input wire CLR,
input wire CE,
input wire [2:0] PC_OP,
input wire [15:0] JDATA,
input wire [15:0] RR,
input wire [7:0] RDATA,
output wire [15:0] PC
);
reg [15:0] LPC;
reg [7:0] LRET;
  assign PC = LPC;
  always @(posedge CLK_I) begin
    if((T2 == 1'b1)) begin
      if((CLR == 1'b1)) begin
        LPC <= 16'h0000;
      end
      else if((CE == 1'b1)) begin
        case(PC_OP)
        PC_NEXT : begin
          LPC <= LPC + 1;
          // next address
        end
        PC_JMP : begin
          LPC <= JDATA;
          // jump address
        end
        PC_RETL : begin
          LRET <= RDATA;
          // return address L
          LPC <= LPC + 1;
        end
        PC_RETH : begin
          LPC <= {RDATA,LRET};
          // return address H
        end
        PC_JPRR : begin
          LPC <= RR;
        end
        PC_WAIT : begin
        end
        default : begin
          LPC <= 16'h0008;
          // interrupt
        end
        endcase
      end
    end
  end
endmodule

