module Control(
    input wire clk,
    input wire [7:0] data_in,
    input wire tx_send,
    output reg [7:0] data_out,
    output reg ctrl_dac,
    output reg [15:0] dato_dac,
    output reg [1:0] mux_dpot,
    output reg ctrl_dpot,
    output reg [7:0] dato_dpot,
    output reg [6:0] seg
);

    reg [7:0] count;
    reg [1:0] estado;

    initial begin
        data_out = 8'h00;
        ctrl_dac = 1'b0;
        dato_dac = 16'h0000;
        mux_dpot = 2'b00;
        ctrl_dpot = 1'b0;
        dato_dpot = 8'h00;
        seg = 7'b1111111;
        count = 8'h00;
        estado = 2'b00;
    end

    always @(posedge clk) begin
        case (mux_dpot)
            2'b00: seg <= 7'b1000000;
            2'b01: seg <= 7'b1111001;
            2'b10: seg <= 7'b0100100;
            2'b11: seg <= 7'b0110000;
        endcase

        if (tx_send) begin
            case (data_in)
                8'h72: begin
                    dato_dac <= 16'h0000;
                    data_out <= 8'h72;
                    estado <= 2'b01;
                end
                8'h74: begin
                    dato_dac <= dato_dac + 1;
                    data_out <= 8'h74;
                    estado <= 2'b01;
                end
                8'h65: begin
                    dato_dac <= dato_dac - 1;
                    data_out <= 8'h65;
                    estado <= 2'b01;
                end
                8'h66: begin
                    dato_dpot <= 8'h00;
                    data_out <= 8'h66;
                    estado <= 2'b10;
                end
                8'h67: begin
                    dato_dpot <= dato_dpot + 1;
                    data_out <= 8'h67;
                    estado <= 2'b10;
                end
                8'h64: begin
                    dato_dpot <= dato_dpot - 1;
                    data_out <= 8'h64;
                    estado <= 2'b10;
                end
                8'h61: begin
                    mux_dpot <= mux_dpot + 1;
                    data_out <= 8'h61;
                end
                8'h71: begin
                    mux_dpot <= mux_dpot - 1;
                    data_out <= 8'h71;
                end
            endcase
            count <= 8'h00;
        end else begin
            count <= count + 1;
            case (estado)
                2'b01: begin
                    if (count < 8'd68) begin
                        ctrl_dac <= 1'b1;
                    end else begin
                        ctrl_dac <= 1'b0;
                        estado <= 2'b00;
                    end
                end
                2'b10: begin
                    if (count < 8'd36) begin
                        ctrl_dpot <= 1'b1;
                    end else begin
                        ctrl_dpot <= 1'b0;
                        estado <= 2'b00;
                    end
                end
            endcase
        end
    end
endmodule

