module CIC_INTEGRATED_SUB (
    input wire CLK,
    input wire nRST,
    input wire [3:0] idx,
    input wire [2:0] state_idx_reg,
    input wire [CIC_CONFIG_DATA_WIDTH-1:0] CIC_NUMSECS_reg,
    input wire signed [MIDDLE_WIDTH-1:0] Data_In,
    input wire Data_In_Valid,
    input wire [3:0] Data_In_ChIdx,
    output reg signed [MIDDLE_WIDTH-1:0] Data_Out,
    output reg [3:0] Data_Out_ChIdx
);

    parameter MIDDLE_WIDTH = 37;
    parameter CIC_MAX_CHANNELS = 16;
    parameter CIC_CONFIG_DATA_WIDTH = 16;

    reg [1:0] state;
    reg signed [MIDDLE_WIDTH-1:0] Delay_reg [CIC_MAX_CHANNELS-1:0];
    reg signed [MIDDLE_WIDTH-1:0] Data_Out_reg;
    reg [3:0] Data_Out_ChIdx_reg;
    integer i;

    always @(negedge nRST or negedge Data_In_Valid) begin
        if (!nRST) begin
            state <= 2'b00;
            Data_Out_reg <= 0;
            Data_Out_ChIdx_reg <= 0;
        end else begin
            case (state)
                2'b00: begin
                    if (CIC_NUMSECS_reg[idx]) begin
                        state <= 2'b01;
                    end
                end
                2'b01: begin
                    if (state_idx_reg == 3'b011) begin
                        state <= 2'b10;
                    end
                end
                2'b10: begin
                    if (state_idx_reg != 3'b011) begin
                        state <= 2'b01;
                    end else begin
                        state <= 2'b00;
                    end
                    Data_Out_reg <= Delay_reg[Data_In_ChIdx] + Data_In;
                    Data_Out_ChIdx_reg <= Data_In_ChIdx;
                end
            endcase
        end
    end

    always @(negedge nRST or posedge Data_In_Valid) begin
        if (!nRST) begin
            for (i = 0; i < CIC_MAX_CHANNELS; i = i + 1) begin
                Delay_reg[i] <= 0;
            end
        end else begin
            if (state == 2'b01 && state_idx_reg == 3'b011) begin
                for (i = 0; i < CIC_MAX_CHANNELS; i = i + 1) begin
                    Delay_reg[i] <= 0;
                end
            end else if (state == 2'b10) begin
                Delay_reg[Data_In_ChIdx] <= Data_Out_reg;
            end
        end
    end

    always @(*) begin
        if (state == 2'b00 || state == 2'b01) begin
            Data_Out = Data_In;
            Data_Out_ChIdx = Data_In_ChIdx;
        end else begin
            Data_Out = Data_Out_reg;
            Data_Out_ChIdx = Data_Out_ChIdx_reg;
        end
    end

endmodule

