module coproc_1(
input wire clock,
input wire reset,
input wire [31:0] INPUT_1,
input wire INPUT_1_valid,
output wire [31:0] OUTPUT_1
);
//comb_alu_1
wire [31:0] mem;
wire [7:0] val0; wire [7:0] val1; wire [7:0] val2; wire [7:0] val3; reg [7:0] min; reg [7:0] max; reg [7:0] max_tmp; reg [7:0] min_tmp;
reg [7:0] max01; reg [7:0] max23; reg [7:0] max0123; reg [7:0] min01; reg [7:0] min23; reg [7:0] min0123;
  // Registres contenant les valeurs du min et du max courant
  // Quand reset actif, alors on initialise min et max
  // A chaque écriture dans le coproc, on met à jour le min et le max avec les 4 nouvelles valeurs
  //-----------------------------------------------------------------------
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b1) begin
      min <= {8{1'b1}};
      max <= {8{1'b0}};
    end
    else begin
      if(INPUT_1_valid == 1'b1) begin
        min <= min_tmp;
        max <= max_tmp;
      end
      else begin
        min <= min;
        max <= max;
      end
    end
  end
  //-----------------------------------------------------------------------
  assign val0 = INPUT_1[31:24];
  assign val1 = INPUT_1[23:16];
  assign val2 = INPUT_1[15:8];
  assign val3 = INPUT_1[7:0];
  always @(max, val0, val1, val2, val3, max01, max23, max0123) begin
    if((val0 > val1)) begin
      max01 <= val0;
    end
    else begin
      max01 <= val1;
    end
    if((val2 > val3)) begin
      max23 <= val2;
    end
    else begin
      max23 <= val3;
    end
    if((max01 > max23)) begin
      max0123 <= max01;
    end
    else begin
      max0123 <= max23;
    end
    if((max0123 > max)) begin
      max_tmp <= max0123;
    end
    else begin
      max_tmp <= max;
    end
  end
  always @(min, val0, val1, val2, val3, min01, min23, min0123) begin
    if((val0 < val1)) begin
      min01 <= val0;
    end
    else begin
      min01 <= val1;
    end
    if((val2 < val3)) begin
      min23 <= val2;
    end
    else begin
      min23 <= val3;
    end
    if((min01 < min23)) begin
      min0123 <= min01;
    end
    else begin
      min0123 <= min23;
    end
    if((min0123 < min)) begin
      min_tmp <= min0123;
    end
    else begin
      min_tmp <= min;
    end
  end
  assign OUTPUT_1 = {16'b0000000000000000,min,max};
//architecture logic
endmodule

