module clockgen(
input wire ext_clk,
input wire async_resetb,
output wire clk,
output reg sync_reset
);
//----------------------------------------------------------
// local signals
//----------------------------------------------------------
wire clk_i;
wire locked;
wire clock_from_ibufg;
reg reset; reg reset_sync;
wire clkfb;
wire clk_to_bufg;
wire reset_cond;
  assign clk = clk_i;
  //----------------------------------------------------------
  // clock generation
  //----------------------------------------------------------
  ibufg clock_pin_ibufg(
      .I(ext_clk),
    .O(clock_from_ibufg));
  //----------------------------------------------------------
  // reset synchronizer
  //----------------------------------------------------------
  always @(posedge clock_from_ibufg, posedge async_resetb) begin
    if(async_resetb == 1'b0) begin
      reset <= 1'b1;
      reset_sync <= 1'b1;
    end else begin
      reset <= reset_sync;
      reset_sync <= 1'b0;
    end
  end
  //---------------------------------------------------------- 
  //----------------------------------------------------------
  // PLL
  //----------------------------------------------------------
  pll_base #(
      .clkfbout_mult(6),
    .clkout0_divide(6),
    .clkin_period(10.0))
  pll_inst(
      .clkin(clock_from_ibufg),
    .rst(reset),
    .clkfbout(clkfb),
    .clkfbin(clkfb),
    .clkout0(clk_to_bufg),
    .clkout1(/* open */),
    .clkout2(/* open */),
    .clkout3(/* open */),
    .clkout4(/* open */),
    .clkout5(/* open */),
    .locked(locked));
  bufg gen_clk_bufg(
      .I(clk_to_bufg),
    .O(clk_i));
  //----------------------------------------------------------
  // synchronous reset output
  //----------------------------------------------------------
  assign reset_cond =  ~locked | reset;
  //----------------------------------------------------------
  always @(posedge clk_i, posedge reset_cond) begin
    if(reset_cond == 1'b1) begin
      sync_reset <= 1'b1;
    end else begin
      sync_reset <= 1'b0;
    end
  end
    //----------------------------------------------------------
endmodule

module exp_with_en (
