    input wire rst_n,
    input wire start_sig,
    output reg en
);

    reg [3:0] c1;
    reg [1:0] i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            c1 <= 4'b0000;
            i <= 2'b00;
            en <= 1'b0;
        end
        else if (start_sig) begin
            case (i)
                2'b00: begin
                    if (c1 == 4'd9) begin
                        c1 <= 4'b0000;
                        en <= 1'b0;
                        i <= 2'b01;
                    end
                    else begin
                        c1 <= c1 + 1'b1;
                        en <= 1'b1;
                    end
                end
                2'b01: begin
                    i <= 2'b00;
                end
                default: begin
                    i <= 2'b00;
                end
            endcase
        end
        else begin
            c1 <= 4'b0000;
            i <= 2'b00;
            en <= 1'b0;
        end
    end

endmodule

module sub_208(
