wire [42:0] carry_inA;
wire [42:0] carry_inB;
wire [42:0] carry_res;  // Signals to generate the comparison outputs
wire [2:0] msb_abr;
wire tmp_sign;
wire tmp_eq;
wire tmp_le;
wire tmp_ge;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign output = carry_res[41:1];
  // Other comparison outputs
  // Temporary signals
  assign msb_abr = {in_a[40],in_b[40],carry_res[41]};
  assign tmp_sign = sign;
  assign tmp_eq = in_a == in_b ? 1'b1 : 1'b0;
  assign tmp_le = msb_abr == 3'b000 || msb_abr == 3'b110 ? tmp_eq : msb_abr == 3'b001 || msb_abr == 3'b111 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b010 || msb_abr == 3'b011) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : 1'b0;
  assign tmp_ge = msb_abr == 3'b000 || msb_abr == 3'b110 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b010 || msb_abr == 3'b011) ? 1'b1 : 1'b0;
  assign ge = tmp_ge;
endmodule

