module Ripple_Counter(
input wire [3:0] A,
input wire [3:0] B,
input wire Cin,
output reg [3:0] Res,
output reg Cout
);
reg [4:0] c;
  always @(A, B, c, Cin) begin
    // Condicion inicial
    c[0] <= Cin;
    for (i=0; i <= 3; i = i + 1) begin
      Res[i] <= A[i] ^ B[i] ^ c[i];
      c[i + 1] <= (A[i] & B[i]) | (A[i] & c[i]) | (B[i] & c[i]);
    end
    // Condicion final
    Cout <= c[4];
  end
endmodule

