module multiplexer(
    input [7:0] in,
    input [2:0] address,
    output out
);
    wire [2:0] not_address;
    wire [7:0] and_out;

    not(not_address[0], address[0]);
    not(not_address[1], address[1]);
    not(not_address[2], address[2]);

    and(and_out[0], in[0], not_address[2], not_address[1], not_address[0]);
    and(and_out[1], in[1], not_address[2], not_address[1], address[0]);
    and(and_out[2], in[2], not_address[2], address[1], not_address[0]);
    and(and_out[3], in[3], not_address[2], address[1], address[0]);
    and(and_out[4], in[4], address[2], not_address[1], not_address[0]);
    and(and_out[5], in[5], address[2], not_address[1], address[0]);
    and(and_out[6], in[6], address[2], address[1], not_address[0]);
    and(and_out[7], in[7], address[2], address[1], address[0]);

    or(out, and_out[0], and_out[1], and_out[2], and_out[3],
              and_out[4], and_out[5], and_out[6], and_out[7]);
endmodule

module signal_sync (
    input  wire i_clk,           // System clock
    input  wire i_rst_n,         // Active-low asynchronous reset
    input  wire i_signal_async,  // Asynchronous input signal
    output wire o_signal_sync    // Synchronized output signal
);

    // Three-stage synchronizer registers
    reg r_signal_1, r_signal_2, r_signal_3;

    // Synchronization process
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            // Reset all registers to 0
            r_signal_1 <= 1'b0;
            r_signal_2 <= 1'b0;
            r_signal_3 <= 1'b0;
        end else begin
            // Propagate signal through synchronization chain
            r_signal_1 <= i_signal_async;
            r_signal_2 <= r_signal_1;
            r_signal_3 <= r_signal_2;
        end
    end

    // Assign the final synchronized signal to the output
    assign o_signal_sync = r_signal_3;

endmodule

