module clkdiv #(
    parameter div = 7,
    parameter lvl = div / 2
)(
    input wire clk,
    input wire rst,
    output wire out
);

    reg [2:0] cnt1, cnt2;
    reg clk1, clk2;
    wire clkn;

    assign clkn = ~clk;
    assign out = clk1 | clk2;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            cnt1 <= 3'b0;
            clk1 <= 1'b0;
        end else begin
            if (cnt1 == lvl) begin
                clk1 <= ~clk1;
                cnt1 <= 3'd1;
            end else begin
                cnt1 <= cnt1 + 1'b1;
            end
        end
    end

    always @(posedge clkn or negedge rst) begin
        if (!rst) begin
            if (cnt1 == 3'b0) begin
                cnt2 <= 3'b0;
                clk2 <= 1'b0;
            end
        end else begin
            if (cnt2 == lvl) begin
                clk2 <= ~clk2;
                cnt2 <= 3'd1;
            end else begin
                cnt2 <= cnt2 + 1'b1;
            end
        end
    end

endmodule

