module spi_interface_controller (
    input [2:0] dsp2fpga_spi_ss,
    input dsp2fpga_spi_clk,
    input dsp2fpga_spi_mosi,
    output dsp2fpga_spi_miso,
    output reg [2:0] spi_sla_ss,
    output [2:0] spi_sla_clk,
    output [2:0] spi_sla_mosi,
    input [2:0] spi_sla_miso
);

    // Slave Select Decoding
    always @(*) begin
        case (dsp2fpga_spi_ss)
            3'b010: spi_sla_ss = 3'b101;
            3'b100: spi_sla_ss = 3'b110;
            3'b110: spi_sla_ss = 3'b011;
            default: spi_sla_ss = 3'b111;
        endcase
    end

    // Clock and Data Distribution
    genvar i;
    generate
        for (i = 0; i < 3; i = i + 1) begin : spi_slave_interface
            assign spi_sla_clk[i] = (spi_sla_ss[i] == 1'b0) ? dsp2fpga_spi_clk : 1'b0;
            assign spi_sla_mosi[i] = (spi_sla_ss[i] == 1'b0) ? dsp2fpga_spi_mosi : 1'b1;
        end
    endgenerate

    // MISO Multiplexing
    assign dsp2fpga_spi_miso = (spi_sla_ss == 3'b101) ? spi_sla_miso[0] :
                               (spi_sla_ss == 3'b110) ? spi_sla_miso[1] :
                               (spi_sla_ss == 3'b011) ? spi_sla_miso[2] : 1'b1;

