module fifo #(
    parameter B = 8,  // Bit width of data
    parameter W = 2   // Address width
)(
    input wire clk,
    input wire reset,
    input wire rd,
    input wire wr,
    input wire [B-1:0] w_data,
    output wire empty,
    output wire full,
    output wire [B-1:0] r_data
);

    // Internal registers
    reg [B-1:0] array_reg [0:(2**W)-1];
    reg [W-1:0] w_ptr_reg, r_ptr_reg;
    reg full_reg, empty_reg;

    // Pointer for next write and read
    wire [W-1:0] w_ptr_next, r_ptr_next;
    // Full and empty status for next cycle
    wire full_next, empty_next;

    // Read data is always the data at the current read pointer
    assign r_data = array_reg[r_ptr_reg];

    // Output status flags
    assign full = full_reg;
    assign empty = empty_reg;

    // Calculate next pointer values
    assign w_ptr_next = (wr && !full) ? w_ptr_reg + 1 : w_ptr_reg;
    assign r_ptr_next = (rd && !empty) ? r_ptr_reg + 1 : r_ptr_reg;

    // Calculate next full and empty status
    assign full_next = ((w_ptr_next == r_ptr_reg) && (w_ptr_next != r_ptr_next)) || (full_reg && !rd);
    assign empty_next = (w_ptr_next == r_ptr_next) || (empty_reg && !wr);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            w_ptr_reg <= 0;
            r_ptr_reg <= 0;
            full_reg <= 0;
            empty_reg <= 1;
        end else begin
            // Update write pointer and perform write
            if (wr && !full) begin
                array_reg[w_ptr_reg] <= w_data;
                w_ptr_reg <= w_ptr_next;
            end

            // Update read pointer
            if (rd && !empty) begin
                r_ptr_reg <= r_ptr_next;
            end

            // Update full and empty status
            full_reg <= full_next;
            empty_reg <= empty_next;
        end
    end

endmodule

