module controller_PmodALS(
    input wire sw,
    input wire rst,
    input wire clk,
    input wire sdo,
    output reg scl,
    output reg cs,
    output reg [15:0] out
);

    reg [6:0] counter;
    reg [15:0] data;
    reg [4:0] bit_count;
    reg state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            scl <= 0;
            cs <= 1;
            data <= 0;
            bit_count <= 0;
            state <= 0;
            out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == 49) begin
                scl <= ~scl;
                counter <= 0;
            end

            case (state)
                0: begin // Idle state
                    if (counter == 0 && scl == 0) begin
                        cs <= 0;
                        state <= 1;
                        bit_count <= 0;
                    end
                end
                1: begin // Data acquisition state
                    if (counter == 0 && scl == 1) begin
                        data <= {data[14:0], sdo};
                        bit_count <= bit_count + 1;
                        if (bit_count == 15) begin
                            state <= 0;
                            cs <= 1;
                            if (sw)
                                out <= {data[14:0], sdo};
                            else
                                out <= ({data[14:0], sdo} == 16'h0000) ? 16'hFFFF : 16'h0000;
                        end
                    end
                end
            endcase
        end
    end

endmodule

module ov7670_vga(
input wire clk25,
output reg [4:0] vga_red,
output reg [5:0] vga_green,
output reg [4:0] vga_blue,
output wire vga_hsync,
output wire vga_vsync,
output wire [17:0] frame_addr,
input wire [11:0] frame_pixel
);
// Timing constants
parameter hRez = 640;
parameter hStartSync = 640 + 16;
parameter hEndSync = 640 + 16 + 96;
parameter hMaxCount = 800;
parameter vRez = 480;
parameter vStartSync = 480 + 10;
parameter vEndSync = 480 + 10 + 2;
parameter vMaxCount = 480 + 10 + 2 + 33;
parameter hsync_active = 1'b0;
parameter vsync_active = 1'b0;
reg [9:0] hCounter = 1'b0;
reg [9:0] vCounter = 1'b0;
reg [18:0] address = 1'b0;
reg blank = 1'b1;
  assign frame_addr = address[18:1];
  always @(posedge clk25) begin
    // Count the lines and rows      
    if(hCounter == (hMaxCount - 1)) begin
      hCounter <= {10{1'b0}};
      if(vCounter == (vMaxCount - 1)) begin
        vCounter <= {10{1'b0}};
      end
      else begin
        vCounter <= vCounter + 1;
      end
    end
    else begin
      hCounter <= hCounter + 1;
    end
    if(blank == 1'b0) begin
      vga_red <= {frame_pixel[11:8],1'b0};
      vga_green <= {frame_pixel[7:4],2'b00};
      vga_blue <= {frame_pixel[3:0],1'b0};
    end
    else begin
      vga_red <= {5{1'b0}};
      vga_green <= {6{1'b0}};
      vga_blue <= {5{1'b0}};
    end
    if(vCounter >= vRez) begin
      address <= {19{1'b0}};
      blank <= 1'b1;
    end
    else begin
      if(hCounter < 640) begin
        blank <= 1'b0;
        address <= address + 1;
      end
      else begin
        blank <= 1'b1;
      end
    end
    // Are we in the hSync pulse? (one has been added to include frame_buffer_latency)
    if(hCounter > hStartSync && hCounter <= hEndSync) begin
      vga_hSync <= hsync_active;
    end
    else begin
      vga_hSync <=  ~hsync_active;
    end
    // Are we in the vSync pulse?
    if(vCounter >= vStartSync && vCounter < vEndSync) begin
      vga_vSync <= vsync_active;
    end
    else begin
      vga_vSync <=  ~vsync_active;
    end
  end
endmodule

module SRL32E #(
    parameter [31:0] INIT = 32'h00000000
) (
    input wire CLK,
    input wire CE,
    input wire D,
    input wire [4:0] A,
    output wire Q
);

    reg [31:0] shift_reg;
    wire CLK_d, CE_d, D_d;

    // Timing model
    assign #1 CLK_d = CLK;
    assign #1 CE_d = CE;
    assign #1 D_d = D;

    // Output assignment
    assign Q = shift_reg[A];

    // Shift register logic
    always @(posedge CLK_d) begin
        if (CE_d) begin
            shift_reg <= {shift_reg[30:0], D_d};
        end
    end

    // Initialization
    initial begin
        shift_reg = INIT;
    end

endmodule

module sub_209(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

