    always @(posedge clk) begin
        cyc <= cyc + 1;
        if (cyc == 2) begin
            if (array[2][1] !== 8'b10_01_0010) $stop;
            for (integer i = 0; i < 3; i = i + 1) begin
                for (integer j = 0; j < 3; j = j + 1) begin
                    if (array[i][j] !== {i[1:0], j[1:0], cyc[3:0]}) $stop;
                end
            end
            $write("*-* All Finished *-*\n");
        end
        if (cyc == 9) begin
            $finish;
        end
    end

    generate
        for (genvar i = 0; i < 3; i = i + 1) begin : row
            for (genvar j = 0; j < 3; j = j + 1) begin : col
                inst u_inst (
                    .cyc(cyc),
                    .i0(i[1:0]),
                    .i1(j[1:0]),
                    .q(array[i][j])
                );
            end
        end
    endgenerate

endmodule

