module GreenDroidADDMPCore(
input wire [31:0] i00,
input wire [31:0] i01,
output reg [31:0] r00,
output reg [31:0] r01,
input wire [31:0] FP,
output reg [31:0] FPout,
output reg [31:0] M_ADDR,
inout reg [31:0] M_DATA,
inout reg M_RD,
inout reg M_WR,
input wire M_RDY,
input wire reset,
input wire CLK
);
parameter [2:0]
  ST_INIT = 0,
  WS_INIT = 1,
  ST_RESET = 2,
  ST00 = 3,
  WS00 = 4,
  ST_END = 5;
reg [2:0] Mstate;
  // CONTROL PROCESS --------
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      Mstate <= ST_RESET;
    end else begin
      case(Mstate)
      ST_RESET : begin
        Mstate <= ST_INIT;
      end
      ST_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
        else begin
          Mstate <= WS_INIT;
        end
      end
      WS_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
      end
      ST00,WS00,ST_END : begin
      end
      default : begin
      end
      endcase
    end
  end
  // EXECUTE PROCESS --------
  always @(posedge clk, posedge reset) begin : P1
    reg [31:0] T, s0, s1, s2, s3, s4, s5, s6, s7, fpi;
    if((reset == 1'b1)) begin
      // reset any internal states -- 
      s0 = {1{1'b0}};
      s1 = {1{1'b0}};
      s2 = {1{1'b0}};
      s3 = {1{1'b0}};
      s4 = {1{1'b0}};
      s5 = {1{1'b0}};
      s6 = {1{1'b0}};
      s7 = {1{1'b0}};
      fpi = {1{1'b0}};
      M_ADDR <= {32{1'bZ}};
      M_DATA <= {32{1'bZ}};
      M_RD <= 1'bZ;
      M_WR <= 1'bZ;
    end else begin
      M_DATA <= 32'bZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ;
      case(Mstate)
      ST_INIT : begin
        // connect 2 input params here --
        s0 = i00;
        s1 = i01;
        fpi = FP;
        //add ;
        s0 = s0 + s1;
        s1 = s2;
        s2 = s3;
        s3 = s4;
        s4 = s5;
        s5 = s6;
        s6 = s7;
        //copy1 ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        // recover 2 results here --
        r00 <= s0;
        r01 <= s1;
        FPout <= fpi;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

module my_Project_373 (
    input wire PCLK,
    input wire PRESERN,
    input wire PSEL,
    input wire PENABLE,
    input wire PWRITE,
    input wire [31:0] PADDR,
    input wire [31:0] PWDATA,
    output wire PREADY,
    output wire PSLVERR,
    output reg [31:0] PRDATA,
    output wire IN1_OUT,
    output wire IN2_OUT,
    output wire IN3_OUT,
    output wire IN4_OUT,
    input wire sensor,
    output wire ENABLE,
    output wire IR_LED_OUT
);

    // APB signals
    assign PREADY = 1'b1;
    assign PSLVERR = 1'b0;

    // Sensor enable
    assign ENABLE = sensor;

    // State machine parameters
    localparam ACTIVE = 1'b0;
    localparam COOLDOWN = 1'b1;

    // Registers
    reg [9:0] pulse_width1, pulse_width2, pulse_width3, pulse_width4;
    reg [31:0] count, count2;
    reg state;

    // Write enable signals
    wire wr_en1, wr_en2, wr_en3, wr_en4;
    assign wr_en1 = PSEL && PENABLE && PWRITE && (PADDR == 32'h04);
    assign wr_en2 = PSEL && PENABLE && PWRITE && (PADDR == 32'h08);
    assign wr_en3 = PSEL && PENABLE && PWRITE && (PADDR == 32'h10);
    assign wr_en4 = PSEL && PENABLE && PWRITE && (PADDR == 32'h14);

    // PWM modules
    pulsewm pwm1 (.clk(PCLK), .rst_n(PRESERN), .pulse_width(pulse_width1), .pwm_out(IN1_OUT));
    pulsewm pwm2 (.clk(PCLK), .rst_n(PRESERN), .pulse_width(pulse_width2), .pwm_out(IN2_OUT));
    pulsewm pwm3 (.clk(PCLK), .rst_n(PRESERN), .pulse_width(pulse_width3), .pwm_out(IN3_OUT));
    pulsewm pwm4 (.clk(PCLK), .rst_n(PRESERN), .pulse_width(pulse_width4), .pwm_out(IN4_OUT));

    // LED module
    LED led_ctrl (.clk(PCLK), .rst_n(PRESERN), .led_out(IR_LED_OUT));

    // Main control logic
    always @(posedge PCLK or negedge PRESERN) begin
        if (!PRESERN) begin
            pulse_width1 <= 10'd0;
            pulse_width2 <= 10'd0;
            pulse_width3 <= 10'd0;
            pulse_width4 <= 10'd0;
            count <= 32'd0;
            count2 <= 32'd0;
            state <= ACTIVE;
        end else begin
            case (state)
                ACTIVE: begin
                    if (wr_en1) pulse_width1 <= PWDATA[9:0];
                    if (wr_en2) pulse_width2 <= PWDATA[9:0];
                    if (wr_en3) pulse_width3 <= PWDATA[9:0];
                    if (wr_en4) pulse_width4 <= PWDATA[9:0];

                    if (!sensor) begin
                        state <= COOLDOWN;
                        count <= 32'd0;
                    end
                end

                COOLDOWN: begin
                    if (count < 32'd1000000) begin
                        count <= count + 1;
                    end else if (count2 < 32'd10000000) begin
                        pulse_width1 <= 10'd0;
                        pulse_width2 <= 10'd0;
                        pulse_width3 <= 10'd0;
                        pulse_width4 <= 10'd0;
                        count2 <= count2 + 1;
                    end else if (sensor) begin
                        state <= ACTIVE;
                        count <= 32'd0;
                        count2 <= 32'd0;
                    end
                end
            endcase
        end
    end

    // APB read operation (not specified in the description, but added for completeness)
    always @(posedge PCLK) begin
        if (PSEL && !PWRITE) begin
            case (PADDR)
                32'h04: PRDATA <= {22'b0, pulse_width1};
                32'h08: PRDATA <= {22'b0, pulse_width2};
                32'h10: PRDATA <= {22'b0, pulse_width3};
                32'h14: PRDATA <= {22'b0, pulse_width4};
                default: PRDATA <= 32'h0;
            endcase
        end
    end

endmodule

module pulsewm (
    input wire clk,
    input wire rst_n,
    input wire [9:0] pulse_width,
    output reg pwm_out
);

    reg [9:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 10'd0;
            pwm_out <= 1'b0;
        end else begin
            if (counter < 10'd999) begin
                counter <= counter + 1;
            end else begin
                counter <= 10'd0;
            end

            pwm_out <= (counter < pulse_width);
        end
    end

endmodule

module LED (
