    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 12'd0;
            led_out <= 1'b0;
        end else begin
            if (counter < 12'd2631) begin
                counter <= counter + 1;
            end else begin
                counter <= 12'd0;
            end

            led_out <= (counter < 12'd1316);
        end
    end

endmodule

