module halfAdder(
    input a, b,
    output s1, s0
);
    assign s0 = a ^ b;
    assign s1 = a & b;
endmodule

module fullAdder(
    input a, b, carryIn,
    output carryOut, s
);
    wire s1, s2, s3;

    halfAdder ha1(.a(a), .b(b), .s1(s1), .s0(s2));
    halfAdder ha2(.a(s2), .b(carryIn), .s1(s3), .s0(s));

    assign carryOut = s1 | s3;
endmodule

module somadorAlg(
    input [2:0] a, b,
    output [3:0] s,
    output zFlag, plus, minus
);
    wire [2:0] b_inv;
    wire [2:0] carry;

    assign b_inv = b ^ 3'b111;

    fullAdder fa0(.a(a[0]), .b(b_inv[0]), .carryIn(1'b1), .carryOut(carry[0]), .s(s[0]));
    fullAdder fa1(.a(a[1]), .b(b_inv[1]), .carryIn(carry[0]), .carryOut(carry[1]), .s(s[1]));
    fullAdder fa2(.a(a[2]), .b(b_inv[2]), .carryIn(carry[1]), .carryOut(s[3]), .s(s[2]));

    assign zFlag = ~(|s);
    assign plus = ~s[3];
    assign minus = s[3];
endmodule

module test_somadorAlg;
    reg [2:0] x, y;
    wire [3:0] s;
    wire zFlag, plus, minus;

    somadorAlg uut(
        .a(x),
        .b(y),
        .s(s),
        .zFlag(zFlag),
        .plus(plus),
        .minus(minus)
    );

    initial begin
        x = 3'b000;
        y = 3'b000;

        // First loop: increment y, then x
        repeat (8) begin
            repeat (8) begin
                #10;
                $display("x=%b, y=%b, s=%b, zFlag=%b, plus=%b, minus=%b", x, y, s, zFlag, plus, minus);
                y = y + 1;
            end
            x = x + 1;
            y = 3'b000;
        end

        // Reset x and y
        x = 3'b000;
        y = 3'b000;

        // Second loop: increment x, then y
        repeat (8) begin
            repeat (8) begin
                #10;
                $display("x=%b, y=%b, s=%b, zFlag=%b, plus=%b, minus=%b", x, y, s, zFlag, plus, minus);
