            end
            y = y + 1;
            x = 3'b000;
        end

        $finish;
    end
endmodule

module epp_interface(
input wire clk,
output reg fifo_rd,
input wire [7:0] fifo_data,
input wire fifo_empty,
input wire epp_astb,
input wire epp_dstb,
output reg epp_wait,
input wire epp_wr,
inout reg [7:0] epp_data
);
parameter [2:0]
  s_idle = 0,
  s_astb_read = 1,
  s_astb_write = 2,
  s_dstb_read = 3,
  s_dstb_write = 4;
reg [2:0] state = s_idle;
reg [1:0] sync_astb = 2'b00;
reg [1:0] sync_dstb = 2'b00;
  always @(*) begin
    case(state)
      s_dstb_read : epp_data <= fifo_data;
      s_astb_read : epp_data <= 8'hAA;
      default : epp_data <= {8{1'bZ}};
    endcase
  end
  always @(posedge clk) begin
    fifo_rd <= 1'b0;
    case(state)
    s_idle : begin
      if(sync_astb[0] == 1'b0) begin
        //------------
        // address strobe
        //------------
        if(epp_wr == 1'b0) begin
          state <= s_astb_write;
        end
        else begin
          state <= s_astb_read;
        end
        epp_wait <= 1'b1;
      end
      else if(sync_dstb[0] == 1'b0) begin
        //------------
        // data strobe
        //------------
        if(epp_wr == 1'b0) begin
          state <= s_dstb_write;
          epp_wait <= 1'b1;
        end
        else begin
          if(fifo_empty == 1'b0) begin
            state <= s_dstb_read;
            epp_wait <= 1'b1;
          end
        end
      end
    end
    s_astb_read : begin
      if(sync_astb[0] == 1'b1) begin
        epp_wait <= 1'b0;
        state <= s_idle;
      end
    end
    s_astb_write : begin
      if(sync_astb[0] == 1'b1) begin
        epp_wait <= 1'b0;
        state <= s_idle;
      end
    end
    s_dstb_read : begin
      if(sync_dstb[0] == 1'b1) begin
        epp_wait <= 1'b0;
        state <= s_idle;
        fifo_rd <= 1'b1;
      end
    end
    s_dstb_write : begin
      if(sync_dstb[0] == 1'b1) begin
        epp_wait <= 1'b0;
        state <= s_idle;
      end
    end
    default : begin
      state <= s_idle;
    end
    endcase
    //-------------------------
    // Sync the strobe signals
    //-------------------------
    sync_astb <= {epp_astb,sync_astb[(1):1]};
    sync_dstb <= {epp_dstb,sync_dstb[(1):1]};
  end
endmodule

