module fsm(
    input clk,
    input w,
    input reset,
    output reg [4:0] out
);

    // State encoding
    localparam A = 4'b0000, B = 4'b0001, C = 4'b0010, D = 4'b0011,
               E = 4'b0100, F = 4'b0101, G = 4'b0110, H = 4'b0111,
               I = 4'b1000;

    reg [3:0] state, next_state;

    // State register
    always @(posedge clk or negedge reset) begin
        if (!reset)
            state <= A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            A: next_state = w ? F : B;
            B: next_state = w ? F : C;
            C: next_state = w ? F : D;
            D: next_state = w ? F : E;
            E: next_state = w ? F : E;
            F: next_state = w ? G : B;
            G: next_state = w ? H : B;
            H: next_state = w ? I : B;
            I: next_state = w ? I : B;
            default: next_state = A;
        endcase
    end

    // Output logic
    always @(*) begin
        out[3:0] = state;
        out[4] = (state == E) || (state == I);
    end

endmodule

module clk6p25m(
    input CLOCK,
    output reg NEWCLOCK
);

reg [2:0] COUNT;

initial begin
    NEWCLOCK = 1'b0;
    COUNT = 3'b000;
end

always @(posedge CLOCK) begin
    if (COUNT == 3'b111) begin
        COUNT <= 3'b000;
        NEWCLOCK <= ~NEWCLOCK;
    end else begin
        COUNT <= COUNT + 1'b1;
    end
end

endmodule

module bcdadder(
input wire [3:0] a,
