output wire cout
);
wire [5:0] raw_sum; wire [5:0] adjusted_sum;
  assign raw_sum = ({1'b0,a,cin}) + ({1'b0,b,cin});
  assign adjusted_sum = (raw_sum < 6'b010100) ? raw_sum : (raw_sum) + 6'b001100;
  assign sum = adjusted_sum[4:1];
  assign cout = adjusted_sum[5];
endmodule

