module apb_bdmac_interface (
    input wire clk,
    input wire rst_n,
    input wire PWRITE,
    input wire PSEL,
    input wire PENABLE,
    input wire [31:0] PWRDATA,
    input wire [31:0] PADDR,
    output reg [31:0] PRDDATA,
    input wire Bref,
    input wire Sref,
    output reg [31:0] BRstAddr,
    output reg [31:0] SRstAddr,
    output reg SPri,
    output reg isCyl,
    output reg BisPlaying,
    output reg Bstop,
    output reg SisPlaying
);

    wire apb_write = PSEL & PWRITE & PENABLE;
    wire [3:0] reg_addr = PADDR[3:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            BRstAddr <= 32'b0;
            SRstAddr <= 32'b0;
            SPri <= 1'b0;
            isCyl <= 1'b0;
            BisPlaying <= 1'b0;
            Bstop <= 1'b0;
            SisPlaying <= 1'b0;
        end else begin
            if (apb_write) begin
                case (reg_addr)
                    4'h0: BRstAddr <= PWRDATA;
                    4'h4: {isCyl, BisPlaying, Bstop} <= PWRDATA[2:0];
                    4'h8: SRstAddr <= PWRDATA;
                    4'hC: {SPri, SisPlaying} <= PWRDATA[1:0];
                endcase
            end

            if (Bref) BisPlaying <= isCyl;
            if (Sref) SisPlaying <= 1'b0;
        end
    end

    always @(*) begin
        case (reg_addr)
            4'h0: PRDDATA = BRstAddr;
            4'h4: PRDDATA = {29'b0, isCyl, BisPlaying, Bstop};
            4'h8: PRDDATA = SRstAddr;
            4'hC: PRDDATA = {30'b0, SPri, SisPlaying};
            default: PRDDATA = 32'b0;
        endcase
    end

endmodule

