output reg [3:0] wrtrigval,
output reg [3:0] wrtrigcfg,
output reg wrspeed,
output reg wrsize,
output reg wrFlags,
output reg arm,
output reg reset
);
wire exe; reg exeReg;
  assign exe = execute;
  always @(posedge clock) begin
    reset <= 1'b0;
    arm <= 1'b0;
    wrspeed <= 1'b0;
    wrsize <= 1'b0;
    wrFlags <= 1'b0;
    wrtrigmask <= 4'b0000;
    wrtrigval <= 4'b0000;
    wrtrigcfg <= 4'b0000;
    if((exe &  ~exeReg) == 1'b1) begin
      case(opcode)
            // short commands
      8'h00 : begin
        reset <= 1'b1;
      end
      8'h01 : begin
        arm <= 1'b1;
        // long commands
      end
      8'h80 : begin
        wrspeed <= 1'b1;
      end
      8'h81 : begin
        wrsize <= 1'b1;
      end
      8'h82 : begin
        wrFlags <= 1'b1;
      end
      8'hC0 : begin
        wrtrigmask[0] <= 1'b1;
      end
      8'hC1 : begin
        wrtrigval[0] <= 1'b1;
      end
      8'hC2 : begin
        wrtrigcfg[0] <= 1'b1;
      end
      8'hC4 : begin
        wrtrigmask[1] <= 1'b1;
      end
      8'hC5 : begin
        wrtrigval[1] <= 1'b1;
      end
      8'hC6 : begin
        wrtrigcfg[1] <= 1'b1;
      end
      8'hC8 : begin
        wrtrigmask[2] <= 1'b1;
      end
      8'hC9 : begin
        wrtrigval[2] <= 1'b1;
      end
      8'hCA : begin
        wrtrigcfg[2] <= 1'b1;
      end
      8'hCC : begin
        wrtrigmask[3] <= 1'b1;
      end
      8'hCD : begin
        wrtrigval[3] <= 1'b1;
      end
      8'hCE : begin
        wrtrigcfg[3] <= 1'b1;
      end
      default : begin
      end
      endcase
    end
    exeReg <= exe;
  end
endmodule

