module CNE_01300_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_Enable,
output wire [3:0] o_Count
);
// Main clock signal
// Main reset signal
// Enables the counter
// Counter (unsigned value)
reg [3:0] Count;  // Counter output signal (unsigned converted)
parameter Length = 4'b1001;  // Counter period
  // Will count undefinitely from 0 to i_Length while i_Enable is asserted
  always @(posedge i_Reset_n, posedge i_Clock) begin
    if((i_Reset_n == 1'b0)) begin
      Count <= {4{1'b0}};
    end else begin
      if((Count >= Length)) begin
        // Counter restarts from 0
        Count <= {4{1'b0}};
      end
      else if((i_Enable == 1'b1)) begin
        // Increment counter value
        Count <= Count + 1;
      end
    end
  end
  assign o_Count = Count;
endmodule
